/**
 * Tests for the Enhance Prompt API Route
 *
 * Tests authentication, rate limiting, and prompt enhancement functionality.
 */
import { describe, expect, it, vi, beforeEach, afterEach, Mock } from "vitest"
import { NextRequest } from "next/server"
import { POST } from "./route"

// Mock Clerk auth
vi.mock("@clerk/nextjs/server", () => ({
    auth: vi.fn(),
}))

// Mock Convex fetchMutation
vi.mock("convex/nextjs", () => ({
    fetchMutation: vi.fn(),
}))

// Mock the Convex API import
vi.mock("@/convex/_generated/api", () => ({
    api: {
        rateLimits: {
            checkRateLimit: "rateLimits:checkRateLimit",
        },
    },
}))

// Mock prompt enhancement
vi.mock("@/lib/prompt-enhancement", () => ({
    enhancePrompt: vi.fn(),
    enhanceNegativePrompt: vi.fn(),
    PromptEnhancementError: class PromptEnhancementError extends Error {
        code: string
        status?: number
        constructor(message: string, code: string, status?: number) {
            super(message)
            this.code = code
            this.status = status
        }
    },
}))

import { auth } from "@clerk/nextjs/server"
import { fetchMutation } from "convex/nextjs"
import { enhancePrompt, enhanceNegativePrompt, PromptEnhancementError } from "@/lib/prompt-enhancement"

function createMockRequest(body: Record<string, unknown>): NextRequest {
    const request = new NextRequest("http://localhost:3000/api/enhance-prompt", {
        method: "POST",
        body: JSON.stringify(body),
        headers: { "Content-Type": "application/json" },
    })
    return request
}

describe("/api/enhance-prompt", () => {
    beforeEach(() => {
        vi.clearAllMocks()
    })

    afterEach(() => {
        vi.resetAllMocks()
    })

    describe("Authentication", () => {
        it("should return 401 when user is not authenticated", async () => {
            vi.mocked(auth).mockResolvedValue({ userId: null } as any)

            const request = createMockRequest({ prompt: "test", type: "prompt" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(401)
            expect(data).toEqual({
                success: false,
                error: {
                    code: "UNAUTHORIZED",
                    message: "Authentication required",
                },
            })
        })

        it("should proceed when user is authenticated", async () => {
            vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 9,
                    resetAt: Date.now() + 60000,
                })
                ; (enhancePrompt as Mock).mockResolvedValue({ enhancedText: "enhanced prompt" })

            const request = createMockRequest({ prompt: "test", type: "prompt" })
            const response = await POST(request)

            expect(response.status).toBe(200)
        })
    })

    describe("Rate Limiting", () => {
        it("should return 429 when rate limit is exceeded", async () => {
            const resetAt = Date.now() + 30000
                ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: false,
                    remaining: 0,
                    resetAt,
                })

            const request = createMockRequest({ prompt: "test", type: "prompt" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(429)
            expect(data).toEqual({
                success: false,
                error: {
                    code: "RATE_LIMIT_EXCEEDED",
                    message: "Too many requests. Please try again later.",
                },
            })
            expect(response.headers.get("Retry-After")).toBeDefined()
            expect(response.headers.get("X-RateLimit-Remaining")).toBe("0")
        })

        it("should include rate limit headers on successful response", async () => {
            const resetAt = Date.now() + 60000
                ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 9,
                    resetAt,
                })
                ; (enhancePrompt as Mock).mockResolvedValue({ enhancedText: "enhanced" })

            const request = createMockRequest({ prompt: "test", type: "prompt" })
            const response = await POST(request)

            expect(response.headers.get("X-RateLimit-Remaining")).toBe("9")
            expect(response.headers.get("X-RateLimit-Reset")).toBe(String(resetAt))
        })
    })

    describe("Validation", () => {
        beforeEach(() => {
            ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 9,
                    resetAt: Date.now() + 60000,
                })
        })

        it("should return 400 when prompt is missing", async () => {
            const request = createMockRequest({ type: "prompt" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(400)
            expect(data.error.code).toBe("VALIDATION_ERROR")
            expect(data.error.message).toBe("Prompt is required")
        })

        it("should return 400 when prompt is empty", async () => {
            const request = createMockRequest({ prompt: "   ", type: "prompt" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(400)
            expect(data.error.code).toBe("VALIDATION_ERROR")
        })

        it("should return 400 when type is invalid", async () => {
            const request = createMockRequest({ prompt: "test", type: "invalid" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(400)
            expect(data.error.code).toBe("VALIDATION_ERROR")
            expect(data.error.message).toBe("Type must be 'prompt' or 'negative'")
        })
    })

    describe("Prompt Enhancement", () => {
        beforeEach(() => {
            ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 9,
                    resetAt: Date.now() + 60000,
                })
        })

        it("should enhance positive prompt successfully", async () => {
            ; (enhancePrompt as Mock).mockResolvedValue({ enhancedText: "enhanced positive prompt" })

            const request = createMockRequest({ prompt: "a cat", type: "prompt" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(200)
            expect(data).toEqual({
                success: true,
                data: { enhancedText: "enhanced positive prompt" },
            })
            expect(enhancePrompt).toHaveBeenCalledWith("a cat", expect.any(Object))
        })

        it("should enhance negative prompt successfully", async () => {
            ; (enhanceNegativePrompt as Mock).mockResolvedValue({ enhancedText: "enhanced negative prompt" })

            const request = createMockRequest({ prompt: "a cat", negativePrompt: "blurry", type: "negative" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(200)
            expect(data.data.enhancedText).toBe("enhanced negative prompt")
            expect(enhanceNegativePrompt).toHaveBeenCalledWith("a cat", "blurry", expect.any(Object))
        })
    })

    describe("Error Handling", () => {
        beforeEach(() => {
            ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 9,
                    resetAt: Date.now() + 60000,
                })
        })

        it("should handle PromptEnhancementError with custom status", async () => {
            const error = new (PromptEnhancementError as unknown as new (message: string, code: string, status?: number) => Error & { code: string; status?: number })("API Error", "API_ERROR", 503)
                ; (enhancePrompt as Mock).mockRejectedValue(error)

            const request = createMockRequest({ prompt: "test", type: "prompt" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(503)
            expect(data.error.code).toBe("API_ERROR")
        })

        it("should handle unknown errors with 500 status", async () => {
            ; (enhancePrompt as Mock).mockRejectedValue(new Error("Unknown error"))

            const request = createMockRequest({ prompt: "test", type: "prompt" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(500)
            expect(data.error.code).toBe("INTERNAL_ERROR")
        })
    })
})

/**
 * Tests for the Suggestions API Route
 *
 * Tests authentication, rate limiting, and suggestion generation functionality.
 */
import { describe, expect, it, vi, beforeEach, afterEach, Mock } from "vitest"
import { NextRequest } from "next/server"
import { POST } from "./route"

// Mock Clerk auth
vi.mock("@clerk/nextjs/server", () => ({
    auth: vi.fn(),
}))

// Mock Convex fetchMutation
vi.mock("convex/nextjs", () => ({
    fetchMutation: vi.fn(),
}))

// Mock the Convex API import
vi.mock("@/convex/_generated/api", () => ({
    api: {
        rateLimits: {
            checkRateLimit: "rateLimits:checkRateLimit",
        },
    },
}))

// Mock prompt enhancement (suggestions)
vi.mock("@/lib/prompt-enhancement", () => ({
    generateSuggestions: vi.fn(),
}))

import { auth } from "@clerk/nextjs/server"
import { fetchMutation } from "convex/nextjs"
import { generateSuggestions } from "@/lib/prompt-enhancement"

function createMockRequest(body: Record<string, unknown>): NextRequest {
    const request = new NextRequest("http://localhost:3000/api/suggestions", {
        method: "POST",
        body: JSON.stringify(body),
        headers: { "Content-Type": "application/json" },
    })
    return request
}

describe("/api/suggestions", () => {
    beforeEach(() => {
        vi.clearAllMocks()
    })

    afterEach(() => {
        vi.resetAllMocks()
    })

    describe("Authentication", () => {
        it("should return 401 when user is not authenticated", async () => {
            ; vi.mocked(auth).mockResolvedValue({ userId: null } as any)

            const request = createMockRequest({ prompt: "test" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(401)
            expect(data).toEqual({
                success: false,
                error: {
                    code: "UNAUTHORIZED",
                    message: "Authentication required",
                },
            })
        })

        it("should proceed when user is authenticated", async () => {
            ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 19,
                    resetAt: Date.now() + 60000,
                })
                ; (generateSuggestions as Mock).mockResolvedValue({ suggestions: ["suggestion 1"] })

            const request = createMockRequest({ prompt: "test" })
            const response = await POST(request)

            expect(response.status).toBe(200)
        })
    })

    describe("Rate Limiting", () => {
        it("should return 429 when rate limit is exceeded", async () => {
            const resetAt = Date.now() + 30000
                ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: false,
                    remaining: 0,
                    resetAt,
                })

            const request = createMockRequest({ prompt: "test" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(429)
            expect(data).toEqual({
                success: false,
                error: {
                    code: "RATE_LIMIT_EXCEEDED",
                    message: "Too many requests. Please try again later.",
                },
            })
            expect(response.headers.get("Retry-After")).toBeDefined()
            expect(response.headers.get("X-RateLimit-Remaining")).toBe("0")
        })

        it("should include rate limit headers on successful response", async () => {
            const resetAt = Date.now() + 60000
                ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 19,
                    resetAt,
                })
                ; (generateSuggestions as Mock).mockResolvedValue({ suggestions: [] })

            const request = createMockRequest({ prompt: "" })
            const response = await POST(request)

            expect(response.headers.get("X-RateLimit-Remaining")).toBe("19")
            expect(response.headers.get("X-RateLimit-Reset")).toBe(String(resetAt))
        })

        it("should use suggestions endpoint for rate limiting", async () => {
            ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 19,
                    resetAt: Date.now() + 60000,
                })
                ; (generateSuggestions as Mock).mockResolvedValue({ suggestions: [] })

            const request = createMockRequest({ prompt: "test" })
            await POST(request)

            expect(fetchMutation).toHaveBeenCalledWith(
                "rateLimits:checkRateLimit",
                { userId: "user_123", endpoint: "suggestions" }
            )
        })
    })

    describe("Suggestion Generation", () => {
        beforeEach(() => {
            ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 19,
                    resetAt: Date.now() + 60000,
                })
        })

        it("should generate suggestions successfully", async () => {
            const suggestions = ["add lighting", "add colors", "add style"]
                ; (generateSuggestions as Mock).mockResolvedValue({ suggestions })

            const request = createMockRequest({ prompt: "a beautiful landscape" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(200)
            expect(data).toEqual({
                success: true,
                data: { suggestions },
            })
        })

        it("should handle empty prompt", async () => {
            ; (generateSuggestions as Mock).mockResolvedValue({ suggestions: [] })

            const request = createMockRequest({ prompt: "" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(200)
            expect(data.success).toBe(true)
            expect(data.data.suggestions).toEqual([])
        })

        it("should handle missing prompt", async () => {
            ; (generateSuggestions as Mock).mockResolvedValue({ suggestions: [] })

            const request = createMockRequest({})
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(200)
            // Should not error, just return empty suggestions
            expect(data.success).toBe(true)
        })
    })

    describe("Error Handling", () => {
        beforeEach(() => {
            ; vi.mocked(auth).mockResolvedValue({ userId: "user_123" } as any)
                ; (fetchMutation as Mock).mockResolvedValue({
                    allowed: true,
                    remaining: 19,
                    resetAt: Date.now() + 60000,
                })
        })

        it("should return empty suggestions on error (graceful degradation)", async () => {
            ; (generateSuggestions as Mock).mockRejectedValue(new Error("API Error"))

            const request = createMockRequest({ prompt: "test" })
            const response = await POST(request)
            const data = await response.json()

            // Should return success with empty suggestions to not break UI
            expect(response.status).toBe(200)
            expect(data.success).toBe(true)
            expect(data.data.suggestions).toEqual([])
        })

        it("should handle AbortError with 499 status", async () => {
            const abortError = new Error("Aborted")
            abortError.name = "AbortError"
                ; (generateSuggestions as Mock).mockRejectedValue(abortError)

            const request = createMockRequest({ prompt: "test" })
            const response = await POST(request)
            const data = await response.json()

            expect(response.status).toBe(499)
            expect(data.error.code).toBe("CANCELLED")
        })
    })
})

import { CommunitySection } from "@/components/landing/community-section";
import { CtaSection } from "@/components/landing/cta-section";
import { FeaturesSection } from "@/components/landing/features-section";
// import { FloatingGallery } from "@/components/landing/floating-gallery";
import { Footer } from "@/components/layout/footer";
import { GLBackground } from "@/components/landing/gl-background";
import { HeroSection } from "@/components/landing/hero-section";
import { LandingHeader } from "@/components/landing/landing-header";
// import { LivingStrip } from "@/components/landing/living-strip";
import { ModelsSection } from "@/components/landing/models-section";
import { ShowcaseSection } from "@/components/landing/showcase-section";
import { ValuePropSection } from "@/components/landing/value-prop-section";
import { JsonLd } from "@/components/seo/json-ld";

/**
 * Landing Page - Server Component
 *
 * Premium landing page with hero, features showcase, model gallery,
 * and compelling value proposition. Inspired by Leonardo.ai's layout
 * but with unique creative elements.
 *
 * ARCHITECTURE FOR SEO:
 * - This page is a SERVER COMPONENT, meaning all static content
 *   (Hero, Features, Models, CTA, Footer) is rendered on the server
 *   and included in the initial HTML response for optimal SEO.
 *
 * - Interactive/client-only parts are isolated into Client Components:
 *   - LandingHeader: Uses hooks for scroll detection and auth state
 *   - GLBackground: Dynamically loads WebGL canvas with ssr:false
 *
 * - This separation ensures search engines receive fully-rendered
 *   static content while users get the enhanced interactive experience.
 */
export default function LandingPage() {
  return (
    <div className="dark">
      <JsonLd
        data={{
          "@context": "https://schema.org",
          "@type": "SoftwareApplication",
          name: "Bloom Studio",
          applicationCategory: "DesignApplication",
          operatingSystem: "Web Browser",
          offers: {
            "@type": "Offer",
            price: "0",
            priceCurrency: "USD",
          },
          description: "Cheap and powerful AI image and video generator studio.",
        }}
      />
      {/* Client Component: WebGL background (ssr: false, won't impact SEO) */}
      <GLBackground />

      {/* Client Component: Interactive header with scroll/auth */}
      <LandingHeader />

      {/* Static content - Server Rendered for SEO */}
      <div className="relative z-[1] pt-0">
        {/* <FloatingGallery /> */}

        <HeroSection />
        {/* LivingStrip removed as requested */}
        <ShowcaseSection />
        <ValuePropSection />
        <FeaturesSection />
        <ModelsSection />
        {/*<CommunitySection />*/}
        <CtaSection />

        {/* Footer */}
        <Footer />
      </div>
    </div>
  );
}

"use client"

import { PaginatedImageGrid } from "@/components/gallery/paginated-image-grid"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { api } from "@/convex/_generated/api"
import { useProfileImages } from "@/hooks/queries/use-image-history"
import { invalidateFollowChange } from "@/app/_server/actions/invalidation"
import { useMutation, useQuery } from "convex/react"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { Loader2, LogIn, Plus, UserCheck } from "lucide-react"
import Link from "next/link"
import { ProfileSkeleton } from "@/components/profile/profile-skeleton"
import { useParams } from "next/navigation"
import { useEffect, useState } from "react"
import { toast } from "sonner"

export default function ProfilePage() {
    const params = useParams()
    const username = params.username as string

    // Fetch user profile
    const userProfile = useQuery(api.users.getUserProfile, { username })

    // Fetch images
    const { results, status, loadMore } = useProfileImages(username)

    // Auto-load more if we got an empty page but aren't done
    useEffect(() => {
        if (status === "CanLoadMore" && results.length === 0) {
            loadMore(20)
        }
    }, [status, results.length, loadMore])

    if (userProfile === undefined) {
        return <ProfileSkeleton />
    }

    if (userProfile === null) {
        return <ProfileNotFound />
    }

    return (
        <div className="min-h-screen pt-4 pb-4">
            <div className="container mx-auto px-4 space-y-4">
                {/* Compact Header */}
                <div className="flex items-center gap-4 py-2">
                    <Avatar className="h-12 w-12 border border-primary/20 shrink-0">
                        <AvatarImage src={userProfile.pictureUrl} alt={userProfile.username} />
                        <AvatarFallback className="text-sm">
                            {userProfile.username?.slice(0, 2).toUpperCase()}
                        </AvatarFallback>
                    </Avatar>

                    <div className="flex-1 min-w-0">
                        <h1 className="text-xl font-bold truncate">{userProfile.username}</h1>
                        <div className="flex items-center gap-4 text-xs text-muted-foreground">
                            <span><span className="font-semibold text-foreground">{userProfile.imagesCount ?? 0}</span> creations</span>
                            <span><span className="font-semibold text-foreground">{userProfile.followersCount ?? 0}</span> followers</span>
                            <span><span className="font-semibold text-foreground">{userProfile.followingCount ?? 0}</span> following</span>
                        </div>
                    </div>

                    <FollowButton followeeId={userProfile.clerkId} />
                </div>

                {/* Grid - the hero */}
                <div className="border-t border-border/40 pt-4">
                    <PaginatedImageGrid
                        images={results}
                        status={status}
                        loadMore={loadMore}
                        showUser={false} // Don't show user badge on their own profile
                        emptyState={
                            <div className="text-center py-20 text-muted-foreground">
                                This user hasn&apos;t shared any public images yet.
                            </div>
                        }
                    />
                </div>
            </div>
        </div>
    )
}

function FollowButton({ followeeId }: { followeeId: string }) {
    const currentUser = useQuery(api.users.getCurrentUser)
    const isFollowing = useQuery(api.follows.isFollowing, { followeeId })
    const follow = useMutation(api.follows.follow)
    const unfollow = useMutation(api.follows.unfollow)
    const [isLoading, setIsLoading] = useState(false)

    const isSelf = currentUser?.clerkId === followeeId

    if (isSelf) return null
    if (isFollowing === undefined || currentUser === undefined) return <Button disabled variant="outline" className="w-32"><Loader2 className="h-4 w-4 animate-spin" /></Button>

    if (currentUser === null) {
        return (
            <Tooltip delayDuration={200}>
                <TooltipTrigger asChild>
                    <Link href="/sign-in" className="inline-flex items-center justify-center whitespace-nowrap rounded-full text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 bg-primary text-primary-foreground hover:bg-primary/90 h-10 px-4 py-2 w-32">
                        <Plus className="mr-2 h-4 w-4" />
                        Follow
                    </Link>
                </TooltipTrigger>
                <TooltipContent side="top">
                    <div className="flex items-center gap-2">
                        <LogIn className="h-3.5 w-3.5" />
                        <p className="font-medium">Sign in to follow</p>
                    </div>
                </TooltipContent>
            </Tooltip>
        )
    }

    const handleFollowToggle = async () => {
        setIsLoading(true)
        try {
            if (isFollowing) {
                await unfollow({ followeeId })
                toast.success("Unfollowed")
            } else {
                await follow({ followeeId })
                toast.success("Followed")
            }
            // Invalidate following feed cache so it reflects the change
            await invalidateFollowChange()
        } catch (error) {
            toast.error("Failed to update follow status")
            console.error(error)
        } finally {
            setIsLoading(false)
        }
    }

    return (
        <Button
            variant={isFollowing ? "secondary" : "default"}
            className="w-32 rounded-full font-medium"
            onClick={handleFollowToggle}
            disabled={isLoading}
        >
            {isLoading ? (
                <Loader2 className="h-4 w-4 animate-spin" />
            ) : isFollowing ? (
                <>
                    <UserCheck className="mr-2 h-4 w-4" />
                    Following
                </>
            ) : (
                <>
                    <Plus className="mr-2 h-4 w-4" />
                    Follow
                </>
            )}
        </Button>
    )
}


function ProfileNotFound() {
    return (
        <div className="min-h-screen pt-32 flex flex-col items-center justify-center text-center px-4">
            <h1 className="text-4xl font-bold mb-4">User not found</h1>
            <p className="text-muted-foreground mb-8">The user you are looking for does not exist.</p>
            <Button asChild>
                <Link href="/feed">Back to Feed</Link>
            </Button>
        </div>
    )
}

"use client"

import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
