            // Should not auto-load since we have items
            expect(mockLoadPublicFeedPage).not.toHaveBeenCalled()
        })

        it("does not auto-load when isDone is true", () => {
            const emptyAndDone = {
                page: [],
                continueCursor: null,
                isDone: true,
            }
            
            render(<FeedClient feedType="public" initialPage={emptyAndDone as any} />)
            
