        y: 0,
        transition: {
            type: "spring",
            stiffness: 300,
            damping: 24,
        },
    },
}

// Sparkle animation - gentle floating + scale pulse
const sparkleVariants: Variants = {
    animate: {
        rotate: [0, 8, -8, 0],
        scale: [1, 1.15, 1],
        transition: {
            duration: 2.5,
            repeat: Infinity,
            ease: "easeInOut",
        },
