"use client"

import { useEffect, useRef, useState } from "react"
import { SolutionStep } from "@/lib/seo-config"
import { ScrollReveal } from "@/components/landing/scroll-reveal"

interface SolutionStepsProps {
    steps: SolutionStep[]
    shortTitle: string
}

export function SolutionSteps({ steps, shortTitle }: SolutionStepsProps) {
    const [visibleStepIndex, setVisibleStepIndex] = useState(-1)
    const containerRef = useRef<HTMLDivElement>(null)
    const timersRef = useRef<NodeJS.Timeout[]>([])

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    // Start sequence when container is in view
                    steps.forEach((_, index) => {
                        const timer = setTimeout(() => {
                            setVisibleStepIndex(current => Math.max(current, index))
                        }, index * 1000)
                        timersRef.current.push(timer)
                    })
                    
                    // Only trigger once
                    observer.disconnect()
                }
            },
            { threshold: 0.2 }
        )

        if (containerRef.current) {
            observer.observe(containerRef.current)
        }

        return () => {
            observer.disconnect()
            timersRef.current.forEach(clearTimeout)
        }
    }, [steps])

    return (
        <section className="py-24 relative overflow-hidden">
            <div className="container mx-auto px-6 relative z-10">
                <ScrollReveal>
                    <div className="text-center mb-16">
                        <h2 className="text-3xl md:text-4xl font-bold mb-4">How to create {shortTitle}</h2>
                        <p className="text-muted-foreground max-w-2xl mx-auto">
                            Three simple steps to professional results.
                        </p>
                    </div>
                </ScrollReveal>

                <div ref={containerRef} className="grid md:grid-cols-3 gap-8 relative">
                    {/* Connecting line */}
                    <div className="hidden md:block absolute top-12 left-[16%] right-[16%] h-0.5 bg-gradient-to-r from-transparent via-primary/30 to-transparent z-0" />

                    {steps.map((step, index) => (
                        <ScrollReveal key={index} delay={index * 150}>
                            <div className="relative text-center group">
                                <div className={`w-24 h-24 mx-auto rounded-full bg-background border-4 transition-all duration-700 flex items-center justify-center mb-6 relative z-10 shadow-xl ${
                                    index <= visibleStepIndex ? "border-primary/30" : "border-white/5"
                                }`}>
                                    <span className={`text-4xl font-bold transition-colors duration-700 ${
                                        index <= visibleStepIndex ? "text-primary" : "text-white/10"
                                    }`}>
                                        {index + 1}
                                    </span>
                                </div>
                                <h3 className="text-xl font-bold mb-3">{step.title}</h3>
                                <p className="text-muted-foreground leading-relaxed max-w-xs mx-auto">
                                    {step.description}
                                </p>
                            </div>
                        </ScrollReveal>
                    ))}
                </div>
            </div>
        </section>
    )
}

"use client"

/**
 * ImageCanvas - Main image display area with premium "Creation Nexus" animations
 */

import { Card } from "@/components/ui/card"
import { isVideoContent, MediaPlayer } from "@/components/ui/media-player"
import { cn } from "@/lib/utils"
import type { GeneratedImage } from "@/types/pollinations"
import { AnimatePresence, motion, type Variants } from "framer-motion"
import { ImagePlus, Loader2, Sparkles } from "lucide-react"
import * as React from "react"

// --- Animation Constants ---

const SPRING_CONFIG = { type: "spring", stiffness: 300, damping: 30, mass: 1 } as const

const nexusContainerVariants: Variants = {
    initial: {
        opacity: 0,
        scale: 1,
    },
    empty: {
        opacity: 1,
        scale: 1,
        transition: SPRING_CONFIG,
    },
    generating: {
        opacity: 1,
        scale: 0.95,
        transition: SPRING_CONFIG,
    },
}

// Holographic expansion rings
const echoVariants: Variants = {
    animate: (i: number) => ({
        scale: [1, 2],
        opacity: [0.3, 0],
        transition: {
            duration: 2,
            repeat: Infinity,
            delay: i * 0.6,
            ease: "easeOut",
        },
    }),
}

// Drifting atmospheric nebula
const nebulaVariants: Variants = {
    animate: (i: number) => ({
        x: [0, i % 2 === 0 ? 40 : -40, 0],
        y: [0, i % 2 === 0 ? -30 : 30, 0],
        opacity: [0.1, 0.3, 0.1],
        transition: {
            duration: 8,
            repeat: Infinity,
            ease: "easeInOut",
        },
    }),
}

const hubVariants: Variants = {
    empty: {
        scale: 1,
        borderRadius: "20px",
        backgroundColor: "rgba(var(--primary-rgb), 0.03)",
        borderColor: "rgba(var(--primary-rgb), 0.4)",
    },
    generating: {
        scale: 0.8,
        borderRadius: "999px",
        backgroundColor: "rgba(var(--primary-rgb), 0.1)",
        borderColor: "rgba(var(--primary-rgb), 0.4)",
    },
}

// Symmetrical light ray variants
const lightRayVariants: Variants = {
    initial: { opacity: 0, scale: 0 },
    animate: (i: number) => ({
        opacity: [0, 0.8, 0],
        scale: [0.5, 1.2, 0.5],
        rotate: [0, 180, 360],
        transition: {
            duration: 3,
            repeat: Infinity,
            delay: i * 0.4,
            ease: "easeInOut",
        },
    }),
}

// Text entrance
const textVariants: Variants = {
    initial: { opacity: 0, y: 12, filter: "blur(4px)" },
    animate: { opacity: 1, y: 0, filter: "blur(0px)" },
    exit: { opacity: 0, y: -12, filter: "blur(4px)" },
}

export interface ImageCanvasProps {
    image: GeneratedImage | null
    isGenerating?: boolean
    progress?: number
    onImageClick?: () => void
    children?: React.ReactNode
    className?: string
}

