        setImageLoaded(false)
        setImageError(false)

    }, [image?.url])

    const handleImageLoad = React.useCallback(() => {
        setImageLoaded(true)
    }, [])

    const showPlaceholder = !image || isGenerating

    return (
        <Card
            className={cn(
