                // Restore mocks
                HTMLElement.prototype.getBoundingClientRect = originalGetBoundingClientRect
                if (originalOffsetHeight) {
                    Object.defineProperty(HTMLElement.prototype, 'offsetHeight', originalOffsetHeight)
                } else {
                    // If it wasn't defined on prototype (it usually is on Element), just delete our override if we can,
                    // but safer to just set it back or assume JSDOM defaults.
                    // Actually JSDOM has it as 0 usually.
                    // Ideally we'd restore fully but for this environment simplistic restore is okay or rely on Vitest isolation if threads are used (they are).
                    Object.defineProperty(HTMLElement.prototype, 'offsetHeight', { configurable: true, value: 0 })
                    Object.defineProperty(HTMLElement.prototype, 'clientHeight', { configurable: true, value: 0 })
                }
            }
        })
    })
})

"use client"

/**
 * ImageGallery - Grid of generated images with scroll and selection
 * Follows SRP: Only manages gallery grid display
 * 
 * Performance: Uses virtualization for large galleries (50+ images)
 * to only render visible thumbnails.
 */

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { ScrollArea } from "@/components/ui/scroll-area"
import { cn } from "@/lib/utils"
import { useVirtualizer } from "@tanstack/react-virtual"
import { Eye, EyeOff, ImageOff, Loader2, MoreHorizontal, Trash2 } from "lucide-react"
import * as React from "react"
import { GalleryThumbnail } from "./gallery-thumbnail"

// HACK: Suppress "flushSync was called from inside a lifecycle method" warning
// This is a known issue with TanStack Virtual v3 and React 19 where disabling flushSync
// causes performance regressions, but keeping it enabled triggers this console error.
const originalError = console.error
console.error = (...args) => {
    if (typeof args[0] === "string" && args[0].includes("flushSync was called from inside a lifecycle method")) {
        return
    }
    originalError.apply(console, args)
}

/**
 * Lightweight data structure for gallery thumbnails.
 * Contains only the fields needed for rendering thumbnails.
 * Full image data is loaded on-demand when opening lightbox.
 */
export interface ThumbnailData {
    id: string
    _id?: string
    url: string
    prompt?: string
    visibility?: "public" | "unlisted"
    model?: string
    _creationTime?: number
    contentType?: string
}

/**
 * Memoized thumbnail wrapper - prevents re-renders when parent updates
 * but this specific thumbnail's props haven't changed.
 */
interface ThumbnailItemProps {
    image: ThumbnailData
    isActive: boolean
    isChecked: boolean
    onSelect: (image: ThumbnailData) => void
    onCheckedChange: (id: string, checked: boolean) => void
    showCheckbox: boolean
    size: "sm" | "md" | "lg"
}

const ThumbnailItem = React.memo(function ThumbnailItem({
    image,
    isActive,
    isChecked,
    onSelect,
    onCheckedChange,
    showCheckbox,
    size,
}: ThumbnailItemProps) {
    // Create stable callbacks that use the image's data
    const handleClick = React.useCallback(() => {
        onSelect(image)
    }, [onSelect, image])

    const handleChecked = React.useCallback((checked: boolean) => {
        onCheckedChange(image.id, checked)
    }, [onCheckedChange, image.id])

    return (
        <GalleryThumbnail
            image={image}
            isActive={isActive}
            isChecked={isChecked}
            onClick={handleClick}
            onCheckedChange={handleChecked}
            showCheckbox={showCheckbox}
            size={size}
        />
    )
})

// Size mappings for virtualization calculations
const THUMBNAIL_SIZES = {
    sm: 64,  // w-16 h-16
    md: 96,  // w-24 h-24
    lg: 128, // w-32 h-32
} as const

const GRID_COLUMNS = {
    sm: 4,
    md: 3,
    lg: 2,
} as const

const GAP_SIZE = 8 // gap-2 = 0.5rem = 8px
const PADDING = 8 // p-2 = 0.5rem = 8px

/** Threshold for enabling virtualization (number of images) */
const VIRTUALIZATION_THRESHOLD = 50

/**
 * VirtualizedGalleryGrid - Renders only visible thumbnails for performance
 * Uses IntersectionObserver for automatic infinite scroll loading.
 */
interface VirtualizedGalleryGridProps {
    images: ThumbnailData[]
    activeImageId?: string
    selectedIds: Set<string>
    selectionMode: boolean
    thumbnailSize: "sm" | "md" | "lg"
    onSelect: (image: ThumbnailData) => void
    onCheckedChange: (id: string, checked: boolean) => void
    /** Callback to load more images when reaching the end */
    onLoadMore?: () => void
    /** Whether more content can be loaded */
    canLoadMore?: boolean
    /** Whether content is currently being loaded */
    isLoadingMore?: boolean
}

const VirtualizedGalleryGrid = React.memo(function VirtualizedGalleryGrid({
    images,
    activeImageId,
    selectedIds,
    selectionMode,
    thumbnailSize,
    onSelect,
    onCheckedChange,
    onLoadMore,
    canLoadMore = false,
    isLoadingMore = false,
}: VirtualizedGalleryGridProps) {
    const parentRef = React.useRef<HTMLDivElement>(null)
    const sentinelRef = React.useRef<HTMLDivElement>(null)

    const columns = GRID_COLUMNS[thumbnailSize]
    const itemSize = THUMBNAIL_SIZES[thumbnailSize]
    const rowHeight = itemSize + GAP_SIZE

    // Calculate number of rows
    const rowCount = Math.ceil(images.length / columns)

    const getScrollElement = React.useCallback(() => parentRef.current, [])
    const estimateSize = React.useCallback(() => rowHeight, [rowHeight])

    const virtualizer = useVirtualizer({
        count: rowCount,
        getScrollElement,
        estimateSize,
        overscan: 5, // Render 5 extra rows above/below viewport
        // Disable flushSync to prevent React warning about flushSync in lifecycle methods during render
        // This is a known issue with TanStack Virtual v3 and React 19
        useFlushSync: true,
    })

    const virtualRows = virtualizer.getVirtualItems()

    // Infinite scroll: trigger loadMore when sentinel becomes visible
    React.useEffect(() => {
        const sentinel = sentinelRef.current
        const scrollContainer = parentRef.current
        if (!sentinel || !scrollContainer || !onLoadMore || !canLoadMore || isLoadingMore) {
            return
        }

        const observer = new IntersectionObserver(
            (entries) => {
                const entry = entries[0]
                if (entry?.isIntersecting && canLoadMore && !isLoadingMore) {
                    onLoadMore()
                }
            },
            {
                root: scrollContainer,
                // Trigger when the sentinel is 200px from being visible
                rootMargin: "0px 0px 200px 0px",
                threshold: 0,
            }
        )

        observer.observe(sentinel)

        return () => {
            observer.disconnect()
        }
    }, [onLoadMore, canLoadMore, isLoadingMore])

    return (
        <div
            ref={parentRef}
            className="flex-1 overflow-auto"
            data-testid="gallery-scroll"
        >
            <div
                className="relative w-full"
                style={{
                    height: `${virtualizer.getTotalSize() + PADDING * 2}px`,
                }}
            >
                {virtualRows.map((virtualRow) => {
                    const rowStartIndex = virtualRow.index * columns
                    const rowImages = images.slice(rowStartIndex, rowStartIndex + columns)

                    return (
                        <div
                            key={virtualRow.key}
                            className="absolute top-0 left-0 w-full grid gap-2"
                            style={{
                                height: `${rowHeight}px`,
                                transform: `translateY(${virtualRow.start + PADDING}px)`,
                                gridTemplateColumns: `repeat(${columns}, 1fr)`,
                                paddingLeft: `${PADDING}px`,
                                paddingRight: `${PADDING}px`,
                            }}
                            data-index={virtualRow.index}
                        >
                            {rowImages.map((image) => (
                                <ThumbnailItem
                                    key={image.id}
                                    image={image}
                                    isActive={activeImageId === image.id}
                                    isChecked={selectedIds.has(image.id)}
                                    onSelect={onSelect}
                                    onCheckedChange={onCheckedChange}
                                    showCheckbox={selectionMode}
                                    size={thumbnailSize}
                                />
                            ))}
                        </div>
                    )
                })}
            </div>

            {/* Infinite scroll sentinel - triggers load more when visible */}
            {
                (canLoadMore || isLoadingMore) && (
                    <div
                        ref={sentinelRef}
                        className="flex justify-center items-center py-4"
                        data-testid="load-more-sentinel"
                    >
                        {isLoadingMore && (
                            <Loader2
                                className="h-4 w-4 animate-spin text-muted-foreground"
                                data-testid="loading-spinner"
                            />
                        )}
                    </div>
                )
            }
        </div >
    )
})

/**
 * StandardGalleryGrid - Non-virtualized grid for smaller datasets
 * Uses IntersectionObserver for automatic infinite scroll loading.
 */
interface StandardGalleryGridProps {
    images: ThumbnailData[]
    activeImageId?: string
    selectedIds: Set<string>
    selectionMode: boolean
    thumbnailSize: "sm" | "md" | "lg"
    direction: "horizontal" | "vertical"
    onSelect: (image: ThumbnailData) => void
    onCheckedChange: (id: string, checked: boolean) => void
    /** Callback to load more images when reaching the end */
    onLoadMore?: () => void
    /** Whether more content can be loaded */
    canLoadMore?: boolean
    /** Whether content is currently being loaded */
    isLoadingMore?: boolean
}

const StandardGalleryGrid = React.memo(function StandardGalleryGrid({
    images,
    activeImageId,
    selectedIds,
    selectionMode,
    thumbnailSize,
    direction,
    onSelect,
    onCheckedChange,
    onLoadMore,
    canLoadMore = false,
    isLoadingMore = false,
}: StandardGalleryGridProps) {
    const scrollRef = React.useRef<HTMLDivElement>(null)
    const sentinelRef = React.useRef<HTMLDivElement>(null)

    // Infinite scroll: trigger loadMore when sentinel becomes visible
    React.useEffect(() => {
        const sentinel = sentinelRef.current
        const scrollContainer = scrollRef.current
        if (!sentinel || !scrollContainer || !onLoadMore || !canLoadMore || isLoadingMore) {
            return
        }

        const observer = new IntersectionObserver(
            (entries) => {
                const entry = entries[0]
                if (entry?.isIntersecting && canLoadMore && !isLoadingMore) {
                    onLoadMore()
                }
            },
            {
                root: scrollContainer,
                // Trigger when the sentinel is 200px from being visible
                rootMargin: "0px 0px 200px 0px",
                threshold: 0,
            }
        )

        observer.observe(sentinel)

        return () => {
            observer.disconnect()
        }
    }, [onLoadMore, canLoadMore, isLoadingMore])

    return (
        <ScrollArea className="flex-1" data-testid="gallery-scroll" ref={scrollRef}>
            <div
                className={cn(
                    "p-2",
                    direction === "horizontal"
                        ? "flex gap-2 overflow-x-auto"
                        : "grid gap-2",
                    direction === "vertical" && {
                        "grid-cols-2": thumbnailSize === "lg",
                        "grid-cols-3": thumbnailSize === "md",
                        "grid-cols-4": thumbnailSize === "sm",
                    }
                )}
                data-testid="gallery-grid"
            >
                {images.map((image) => (
                    <ThumbnailItem
                        key={image.id}
                        image={image}
                        isActive={activeImageId === image.id}
                        isChecked={selectedIds.has(image.id)}
                        onSelect={onSelect}
                        onCheckedChange={onCheckedChange}
                        showCheckbox={selectionMode}
                        size={thumbnailSize}
                    />
                ))}
            </div>
            {/* Infinite scroll sentinel - triggers load more when visible */}
            {(canLoadMore || isLoadingMore) && (
                <div
                    ref={sentinelRef}
                    className="flex justify-center items-center py-4"
                    data-testid="load-more-sentinel"
                >
                    {isLoadingMore && (
                        <Loader2
                            className="h-4 w-4 animate-spin text-muted-foreground"
                            data-testid="loading-spinner"
                        />
                    )}
                </div>
            )}
        </ScrollArea>
    )
})

export interface ImageGalleryProps {
    /** Array of thumbnail data for display */
    images: ThumbnailData[]
    /** Currently active/selected image ID */
    activeImageId?: string
    /** Callback when an image is selected (clicked to view in canvas) */
    onSelectImage?: (image: ThumbnailData) => void
    /** Whether bulk selection mode is enabled */
    selectionMode?: boolean
    /** Set of selected image IDs */
    selectedIds?: Set<string>
    /** Callback when selection changes */
    onSelectionChange?: (selectedIds: Set<string>) => void
    /** Callback to toggle selection mode */
    onToggleSelectionMode?: () => void
    /** Callback to delete selected images */
    onDeleteSelected?: () => void
    /** Callback to make selected images public */
    onMakeSelectedPublic?: () => void
    /** Callback to make selected images private */
    onMakeSelectedPrivate?: () => void
    /** Layout direction */
    direction?: "horizontal" | "vertical"
    /** Thumbnail size */
    thumbnailSize?: "sm" | "md" | "lg"
    /** Additional class names */
    className?: string
    /** Callback to load more images */
    onLoadMore?: () => void
    /** Whether more images are being loaded */
    isLoadingMore?: boolean
    /** Whether initial data is loading */
    isLoading?: boolean
    /** Whether all data has been loaded */
    isExhausted?: boolean
    /** Optional content to render when empty and exhausted */
    emptyContent?: React.ReactNode
    /** Optional content to render in the header (e.g., filter controls) */
    headerContent?: React.ReactNode
}

export const ImageGallery = React.memo(function ImageGallery({
    images,
    activeImageId,
    onSelectImage,
    selectionMode = false,
    selectedIds = new Set(),
    onSelectionChange,
    onToggleSelectionMode,
    onDeleteSelected,
    onMakeSelectedPublic,
    onMakeSelectedPrivate,
    direction = "vertical",
    thumbnailSize = "md",
    className,
    onLoadMore,
    isLoadingMore = false,
    isLoading = false,
    isExhausted = false,
    emptyContent,
    headerContent,
}: ImageGalleryProps) {
    // Defer selection state updates to keep UI responsive during rapid changes
    // This allows the UI thread to handle interactions (like clicking Select button)
    // without waiting for all thumbnail checkboxes to update
    const deferredSelectedIds = React.useDeferredValue(selectedIds)

    // Memoized callback for checkbox changes - uses selectedIds ref to avoid recreating on selection changes
    const selectedIdsRef = React.useRef(selectedIds)
    selectedIdsRef.current = selectedIds

    const handleCheckedChange = React.useCallback((imageId: string, checked: boolean) => {
        const newSelection = new Set(selectedIdsRef.current)
        if (checked) {
            newSelection.add(imageId)
        } else {
            newSelection.delete(imageId)
        }
        onSelectionChange?.(newSelection)
    }, [onSelectionChange])

    // Memoized select all - stable reference
    const selectAll = React.useCallback(() => {
        onSelectionChange?.(new Set(images.map((img) => img.id)))
    }, [onSelectionChange, images])

    // Memoized deselect all - stable reference
    const deselectAll = React.useCallback(() => {
        onSelectionChange?.(new Set())
    }, [onSelectionChange])

    // Memoized handler for individual thumbnails - avoid creating new functions in the map
    const handleImageClick = React.useCallback((image: ThumbnailData) => {
        onSelectImage?.(image)
    }, [onSelectImage])

    // Loading state component - displayed inline within the gallery
    const loadingState = (
        <div
            className="flex flex-col items-center justify-center flex-1 text-center p-6"
            data-testid="gallery-loading"
        >
            <Loader2
                className="h-6 w-6 animate-spin text-muted-foreground"
                data-testid="loading-spinner"
            />
        </div>
    )

    // Empty state component - displayed inline within the gallery
    const emptyState = (
        <div
            className="flex flex-col items-center justify-center flex-1 text-center p-6"
            data-testid="gallery-empty"
        >
            <div className="flex items-center justify-center w-12 h-12 rounded-full bg-muted mb-3">
                <ImageOff className="h-5 w-5 text-muted-foreground" />
            </div>
            <p className="text-sm font-medium text-foreground">No images found</p>
            <p className="text-xs text-muted-foreground mt-1">
                {headerContent ? "Try adjusting your filters" : "Generated images will appear here"}
            </p>
        </div>
    )

    // Determine what to render in the content area
    const renderContent = () => {
        if (isLoading) {
            return loadingState
        }
        // FIXED: Only show empty state if exhausted and no images
        if (images.length === 0 && isExhausted) {
            return emptyContent ?? emptyState
        }
        return null // Will render the ScrollArea with images
    }

    const contentState = renderContent()

    return (
        <div
            className={cn("flex flex-col h-full", className)}
            data-testid="image-gallery"
        >
            {/* Header with selection controls */}
            <div className="flex flex-col gap-2 p-2 border-b border-border/50">
                <div className="flex items-center justify-between">
                    <span className="text-xs font-medium text-muted-foreground">
                        History ({images.length})
                    </span>
                    <div className="flex items-center gap-1.5">
                        {selectionMode ? (
                            <>
                                <label
                                    className="flex items-center gap-1.5 cursor-pointer select-none"
                                    data-testid="select-all-label"
                                >
                                    <Checkbox
                                        checked={
                                            images.length === 0
                                                ? false
                                                : selectedIds.size === images.length
                                                    ? true
                                                    : selectedIds.size > 0
                                                        ? "indeterminate"
                                                        : false
                                        }
                                        onCheckedChange={(checked) => {
                                            if (checked) {
                                                selectAll()
                                            } else {
                                                deselectAll()
                                            }
                                        }}
                                        data-testid="select-all"
                                        disabled={images.length === 0}
                                        className="h-3.5 w-3.5"
                                    />
                                    <span className="text-xs text-muted-foreground">
                                        {selectedIds.size > 0 ? `${selectedIds.size} selected` : "Select all"}
                                    </span>
                                </label>
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button
                                            variant="secondary"
                                            size="sm"
                                            className="h-6 px-2 text-xs"
                                            data-testid="bulk-actions-menu"
                                            disabled={selectedIds.size === 0}
                                        >
                                            <MoreHorizontal className="h-3 w-3 mr-1" />
                                            Actions
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="end" className="w-48" collisionPadding={16}>
                                        {onMakeSelectedPublic && (
                                            <DropdownMenuItem
                                                onClick={onMakeSelectedPublic}
                                                data-testid="make-public"
                                            >
                                                <Eye className="h-4 w-4 mr-2" />
                                                Make Public
                                            </DropdownMenuItem>
                                        )}
                                        {onMakeSelectedPrivate && (
                                            <DropdownMenuItem
                                                onClick={onMakeSelectedPrivate}
                                                data-testid="make-private"
                                            >
                                                <EyeOff className="h-4 w-4 mr-2" />
                                                Make Private
                                            </DropdownMenuItem>
                                        )}
                                        {(onMakeSelectedPublic || onMakeSelectedPrivate) && onDeleteSelected && (
                                            <DropdownMenuSeparator />
                                        )}
                                        {onDeleteSelected && (
                                            <DropdownMenuItem
                                                onClick={onDeleteSelected}
                                                variant="destructive"
                                                data-testid="delete-selected"
                                            >
                                                <Trash2 className="h-4 w-4 mr-2" />
                                                Delete Selected
                                            </DropdownMenuItem>
                                        )}
                                    </DropdownMenuContent>
                                </DropdownMenu>
                            </>
                        ) : null}
                        {onToggleSelectionMode && (
                            <Button
                                variant={selectionMode ? "secondary" : "ghost"}
                                size="sm"
                                className="h-6 px-2 text-xs"
                                onClick={onToggleSelectionMode}
                                data-testid="toggle-selection"
                                disabled={images.length === 0 && !selectionMode}
                            >
                                {selectionMode ? "Done" : "Select"}
                            </Button>
                        )}
                    </div>
                </div>
                {/* Optional header content (e.g., filter controls) */}
                {headerContent}
            </div>

            {/* Gallery Grid, Loading State, or Empty State */}
            {contentState ?? (
                images.length >= VIRTUALIZATION_THRESHOLD && direction === "vertical" ? (
                    // Virtualized grid for large datasets with infinite scroll
                    <VirtualizedGalleryGrid
                        images={images}
                        activeImageId={activeImageId}
                        selectedIds={deferredSelectedIds}
                        selectionMode={selectionMode}
                        thumbnailSize={thumbnailSize}
                        onSelect={handleImageClick}
                        onCheckedChange={handleCheckedChange}
                        onLoadMore={onLoadMore}
                        canLoadMore={!!onLoadMore && !isExhausted}
                        isLoadingMore={isLoadingMore}
                    />
                ) : (
                    // Standard grid for smaller datasets or horizontal layout with infinite scroll
                    <StandardGalleryGrid
                        images={images}
                        activeImageId={activeImageId}
                        selectedIds={deferredSelectedIds}
                        selectionMode={selectionMode}
                        thumbnailSize={thumbnailSize}
                        direction={direction}
                        onSelect={handleImageClick}
                        onCheckedChange={handleCheckedChange}
                        onLoadMore={onLoadMore}
                        canLoadMore={!!onLoadMore && !isExhausted}
                        isLoadingMore={isLoadingMore}
                    />
                )
            )}
        </div>
    )
})

"use client"

import {
    ActiveFilterBadges,
    HistoryFiltersDropdown,
    type HistoryFilterState,
} from "@/components/gallery/history-filters"
import type { Id } from "@/convex/_generated/dataModel"
import { useBulkDeleteGeneratedImages } from "@/hooks/mutations/use-delete-image"
import { useSetBulkVisibility } from "@/hooks/mutations/use-set-visibility"
import { useImageHistory, type HistoryFilters } from "@/hooks/queries/use-image-history"
import { useLocalStorage } from "@/hooks/use-local-storage"
import { loadMyHistoryPage } from "@/app/_server/actions/history"
import { useUser } from "@clerk/nextjs"
import * as React from "react"
import { ImageGallery, type ImageGalleryProps, type ThumbnailData } from "./image-gallery"

const INITIAL_FILTER_STATE: HistoryFilterState = {
    selectedVisibility: [],
    selectedModels: [],
}

// Type for the paginated result from server cache
type PaginatedGalleryResult = {
    page: Array<{
        _id: string
        _creationTime: number
        url: string
        visibility?: "public" | "unlisted"
        model?: string
        contentType?: string
    }>
    isDone: boolean
    continueCursor: string
}

/**
 * Props for PersistentImageGallery - excludes props that are managed internally
 */
type PersistentImageGalleryProps = Omit<
    ImageGalleryProps,
    "images" | "headerContent" | "isLoading" | "isExhausted" |
    "onMakeSelectedPublic" | "onMakeSelectedPrivate" | "onDeleteSelected" |
    "selectionMode" | "selectedIds" | "onSelectionChange" | "onToggleSelectionMode"
> & {
    /** Server-cached initial page (reduces Convex bandwidth on initial load) */
    initialPage?: PaginatedGalleryResult
}

/**
 * Smart component that fetches persistent image history from Convex
 * and displays it using the ImageGallery presentational component.
 * 
 * HYBRID CACHING STRATEGY:
 * - Initial page: Uses server-cached data if provided (reduces Convex bandwidth)
 * - Real-time updates: Convex reactive hooks keep the first page fresh
 * - Load more: Uses server actions for subsequent pages (cached)
 * 
 * This gives us the best of both worlds:
 * - Fast initial load from server cache
 * - Instant updates when new images are generated
 * - Reduced Convex bandwidth for pagination
 * 
 * Performance: Manages selection state internally to avoid propagating
 * selection changes to parent components. This prevents unnecessary
 * re-renders when checking/unchecking items.
 * 
 * Includes filter state management for visibility and model filtering.
 */
export function PersistentImageGallery(props: PersistentImageGalleryProps) {
    const { initialPage, ...restProps } = props

    const { user } = useUser()

    // ========================================
    // Internal Selection State (isolated from parent)
    // ========================================
    const [selectionMode, setSelectionMode] = React.useState(false)
    const [selectedIds, setSelectedIds] = React.useState<Set<string>>(new Set())

    // Ref for stable callbacks
    const selectedIdsRef = React.useRef(selectedIds)

    React.useEffect(() => {
        selectedIdsRef.current = selectedIds
    }, [selectedIds])

    // Determine storage key based on user ID for account-specific preferences
    const storageKey = React.useMemo(() =>
        user?.id ? `bloom:studio-filters:${user.id}` : "bloom:studio-filters:anon",
        [user?.id])

    // Filter state persisted to localStorage
    const [filterState, setFilterState] = useLocalStorage<HistoryFilterState>(storageKey, INITIAL_FILTER_STATE)

    // Track if filters have been changed from default (affects caching strategy)
    const hasActiveFilters = filterState.selectedVisibility.length > 0 || filterState.selectedModels.length > 0

    // Mutations
    const setBulkVisibilityMutation = useSetBulkVisibility()
    const bulkDeleteMutation = useBulkDeleteGeneratedImages()

    // Convert filter state to query parameters
    const queryFilters: HistoryFilters = React.useMemo(() => ({
        visibility: filterState.selectedVisibility.length === 1
            ? filterState.selectedVisibility[0]
            : undefined,
        models: filterState.selectedModels.length > 0 ? filterState.selectedModels : undefined,
    }), [filterState])

    // ========================================
    // Hybrid Data Strategy
    // ========================================
    // Use Convex reactive hook for real-time updates (new generations appear instantly)
    const convexQuery = useImageHistory(queryFilters)
    
    // Server-cached pages for "load more" (reduces Convex bandwidth)
    const [cachedPages, setCachedPages] = React.useState<ThumbnailData[]>([])
    const [cachedCursor, setCachedCursor] = React.useState<string | null>(null)
    const [cachedIsDone, setCachedIsDone] = React.useState(false)
    const [isLoadingCached, setIsLoadingCached] = React.useState(false)
    
    // Initialize cached state from server-provided initial page (only if no filters)
    const initializedRef = React.useRef(false)
    React.useEffect(() => {
        if (initialPage && !initializedRef.current && !hasActiveFilters) {
            initializedRef.current = true
            // We don't use the initial page data directly since Convex hook provides
            // the same data with reactivity. But we capture the cursor for "load more".
            setCachedCursor(initialPage.continueCursor || null)
            setCachedIsDone(initialPage.isDone)
        }
    }, [initialPage, hasActiveFilters])
    
    // Reset cached state when filters change
    React.useEffect(() => {
        setCachedPages([])
        setCachedCursor(null)
        setCachedIsDone(false)
        initializedRef.current = false
    }, [queryFilters.visibility, queryFilters.models?.join(",")])

    // Combine Convex results with cached pages
    const convexResults = convexQuery.results
    const convexStatus = convexQuery.status
    const convexLoadMore = convexQuery.loadMore
    
    // Determine overall status
    const isLoading = convexStatus === "LoadingFirstPage"
    const isLoadingMore = convexStatus === "LoadingMore" || isLoadingCached
    
    // For exhausted state: check both Convex and cached
    // If there's no cachedCursor (no initialPage provided), consider cached as done
    const convexExhausted = convexStatus === "Exhausted"
    const effectivelyCachedDone = cachedIsDone || !cachedCursor
    const isExhausted = convexExhausted && effectivelyCachedDone
    const canLoadMore = convexStatus === "CanLoadMore" || (!cachedIsDone && cachedCursor)

    // Combined results: Convex reactive data + cached pages
    const results = React.useMemo(() => {
        // If we have cached pages, append them after Convex results
        // But avoid duplicates by checking IDs (cast to string for comparison)
        const convexIds = new Set(convexResults.map(r => String(r._id)))
        const uniqueCachedPages = cachedPages.filter(p => !convexIds.has(p.id))
        return [...convexResults, ...uniqueCachedPages]
    }, [convexResults, cachedPages])

    // Load more handler - uses server action for cached pages
    const handleLoadMore = React.useCallback(async () => {
        // First, exhaust Convex pagination
        if (convexStatus === "CanLoadMore") {
            convexLoadMore(20)
            return
        }
        
        // Then, load from server cache
        if (!cachedIsDone && cachedCursor && !isLoadingCached) {
            setIsLoadingCached(true)
            try {
                const result = await loadMyHistoryPage({
                    cursor: cachedCursor,
                    numItems: 20,
                    filters: queryFilters,
                })
                
                // Map to ThumbnailData format
                const newImages: ThumbnailData[] = result.page.map(img => ({
                    id: img._id,
                    _id: img._id,
                    _creationTime: img._creationTime,
                    url: img.url,
                    visibility: img.visibility,
                    model: img.model,
                    contentType: img.contentType,
                    prompt: "",
                }))
                
                setCachedPages(prev => [...prev, ...newImages])
                setCachedCursor(result.continueCursor || null)
                setCachedIsDone(result.isDone)
            } catch (error) {
                console.error("Failed to load more from cache:", error)
            } finally {
                setIsLoadingCached(false)
            }
        }
    }, [convexStatus, convexLoadMore, cachedCursor, cachedIsDone, isLoadingCached, queryFilters])

    // Auto-load more if we got an empty page but aren't done
    React.useEffect(() => {
        if (canLoadMore && results.length === 0 && !isLoading && !isLoadingMore) {
            handleLoadMore()
        }
    }, [canLoadMore, results.length, isLoading, isLoadingMore, handleLoadMore])

    // ========================================
    // Stable Image References (prevents full gallery re-render)
    // ========================================
    // When Convex pushes updates, the entire `results` array is replaced with new object references.
    // Without stabilization, every ThumbnailItem would re-render even if its data hasn't changed.
    // We use a cache map to preserve object references for unchanged images.
    const imageCache = React.useRef<Map<string, ThumbnailData>>(new Map())

    const mappedImages = React.useMemo(() => {
        const newCache = new Map<string, ThumbnailData>()

        const stableImages = results.map(img => {
            // Handle both Convex results and cached ThumbnailData
            // Convex results have _id, cached ThumbnailData has id
            const id = "_id" in img ? String(img._id) : (img as ThumbnailData).id
             
            const cached = imageCache.current.get(id)

            // Get values from either format
            const url = img.url
            const visibility = img.visibility
            const model = img.model
            const contentType = img.contentType
            const creationTime = "_creationTime" in img ? img._creationTime : (img as ThumbnailData)._creationTime

            // Check if cached version is still valid (same data)
            // Only compare fields that would affect rendering
            if (cached &&
                cached.url === url &&
                cached.visibility === visibility &&
                cached.model === model &&
                cached.contentType === contentType) {
                // Reuse cached object reference - prevents child re-render
                newCache.set(id, cached)
                return cached
            }

            // Create new object for new/changed images
            const newImage: ThumbnailData = {
                id,
                _id: id,
                _creationTime: creationTime,
                url,
                visibility,
                model,
                contentType,
                prompt: "", // Placeholder - full data loaded on click via getById
            }

            newCache.set(id, newImage)
            return newImage
        })

        // Update cache for next render
         
        imageCache.current = newCache

        return stableImages
    }, [results])

    // ========================================
    // Selection Handlers (stable callbacks)
    // ========================================
    const handleToggleSelectionMode = React.useCallback(() => {
        setSelectionMode(prev => {
            // Clear selection when exiting selection mode
            if (prev) {
                setSelectedIds(new Set())
            }
            return !prev
        })
    }, [])

    const handleSelectionChange = React.useCallback((newSelection: Set<string>) => {
        setSelectedIds(newSelection)
    }, [])

    // ========================================
    // Bulk Action Handlers (stable callbacks using refs)
    // ========================================
    const handleMakeSelectedPublic = React.useCallback(async () => {
        const currentSelectedIds = selectedIdsRef.current
        if (currentSelectedIds.size === 0) return

        const imageIds = Array.from(currentSelectedIds) as Id<"generatedImages">[]
        try {
            await setBulkVisibilityMutation.mutateAsync({ imageIds, visibility: "public" })
            setSelectedIds(new Set())
            setSelectionMode(false)
        } catch (error) {
            console.error("Failed to make images public:", error)
            // The mutation hook already shows toasts
        }
    }, [setBulkVisibilityMutation])

    const handleMakeSelectedPrivate = React.useCallback(async () => {
        const currentSelectedIds = selectedIdsRef.current
        if (currentSelectedIds.size === 0) return

        const imageIds = Array.from(currentSelectedIds) as Id<"generatedImages">[]
        try {
            await setBulkVisibilityMutation.mutateAsync({ imageIds, visibility: "unlisted" })
            setSelectedIds(new Set())
            setSelectionMode(false)
        } catch (error) {
            console.error("Failed to make images private:", error)
            // The mutation hook already shows toasts
        }
    }, [setBulkVisibilityMutation])

    const handleDeleteSelected = React.useCallback(async () => {
        const currentSelectedIds = selectedIdsRef.current
        if (currentSelectedIds.size === 0) return

        const imageIds = Array.from(currentSelectedIds) as Id<"generatedImages">[]
        try {
            // Use bulk delete mutation - single Convex call, single toast
            await bulkDeleteMutation.mutateAsync(imageIds)
            setSelectedIds(new Set())
            setSelectionMode(false)
        } catch (error) {
            console.error("Failed to delete images:", error)
            // The mutation hook already shows error toast
        }
    }, [bulkDeleteMutation])

    // Memoize header content to prevent unnecessary re-renders
    const headerContent = React.useMemo(() => (
        <div className="flex flex-col gap-1.5">
            <HistoryFiltersDropdown
                filters={filterState}
                onFiltersChange={setFilterState}
            />
            <ActiveFilterBadges
                filters={filterState}
                onFiltersChange={setFilterState}
            />
        </div>
    ), [filterState, setFilterState])

    // Memoize load more handler
    const memoizedLoadMore = React.useCallback(() => {
        handleLoadMore()
    }, [handleLoadMore])

    return (
        <ImageGallery
            {...restProps}
            selectionMode={selectionMode}
            selectedIds={selectedIds}
            onSelectionChange={handleSelectionChange}
            onToggleSelectionMode={handleToggleSelectionMode}
            images={mappedImages}
            headerContent={headerContent}
            isLoading={isLoading}
            isExhausted={isExhausted}
            onLoadMore={canLoadMore || isLoadingMore ? memoizedLoadMore : undefined}
            isLoadingMore={isLoadingMore}
            onMakeSelectedPublic={handleMakeSelectedPublic}
            onMakeSelectedPrivate={handleMakeSelectedPrivate}
            onDeleteSelected={handleDeleteSelected}
        />
    )
}

import { describe, it, expect, vi } from "vitest"
import { render, screen, act } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import { SelectionProvider, useSelection, useSelectionMode, useIsSelected } from "./selection-context"

// Test component that uses the selection context
function TestConsumer() {
    const { 
        selectionMode, 
        selectedIds, 
        toggleSelectionMode,
        toggleSelection,
        selectAll,
        deselectAll,
    } = useSelection()
    
    return (
        <div>
            <span data-testid="selection-mode">{selectionMode ? "on" : "off"}</span>
            <span data-testid="selected-count">{selectedIds.size}</span>
            <span data-testid="selected-ids">{Array.from(selectedIds).join(",")}</span>
            <button data-testid="toggle-mode" onClick={toggleSelectionMode}>Toggle Mode</button>
            <button data-testid="toggle-item-1" onClick={() => toggleSelection("item-1")}>Toggle Item 1</button>
            <button data-testid="toggle-item-2" onClick={() => toggleSelection("item-2")}>Toggle Item 2</button>
            <button data-testid="select-all" onClick={() => selectAll(["item-1", "item-2", "item-3"])}>Select All</button>
            <button data-testid="deselect-all" onClick={deselectAll}>Deselect All</button>
        </div>
    )
}

// Test component for useSelectionMode hook
function SelectionModeConsumer() {
    const { selectionMode, toggleSelectionMode } = useSelectionMode()
    return (
        <div>
            <span data-testid="mode-only">{selectionMode ? "on" : "off"}</span>
            <button data-testid="toggle-mode-only" onClick={toggleSelectionMode}>Toggle</button>
        </div>
    )
}

// Test component for useIsSelected hook
function IsSelectedConsumer({ id }: { id: string }) {
    const isSelected = useIsSelected(id)
    return <span data-testid={`is-selected-${id}`}>{isSelected ? "yes" : "no"}</span>
}

describe("SelectionContext", () => {
    describe("SelectionProvider", () => {
        it("provides default state", () => {
            render(
                <SelectionProvider>
                    <TestConsumer />
                </SelectionProvider>
            )
            
            expect(screen.getByTestId("selection-mode")).toHaveTextContent("off")
            expect(screen.getByTestId("selected-count")).toHaveTextContent("0")
        })
        
        it("toggles selection mode", async () => {
            const user = userEvent.setup()
            render(
                <SelectionProvider>
                    <TestConsumer />
                </SelectionProvider>
            )
            
            expect(screen.getByTestId("selection-mode")).toHaveTextContent("off")
            
            await user.click(screen.getByTestId("toggle-mode"))
            expect(screen.getByTestId("selection-mode")).toHaveTextContent("on")
            
            await user.click(screen.getByTestId("toggle-mode"))
            expect(screen.getByTestId("selection-mode")).toHaveTextContent("off")
        })
        
        it("clears selection when exiting selection mode", async () => {
            const user = userEvent.setup()
            render(
                <SelectionProvider>
                    <TestConsumer />
                </SelectionProvider>
            )
            
            // Enter selection mode and select items
            await user.click(screen.getByTestId("toggle-mode"))
            await user.click(screen.getByTestId("toggle-item-1"))
            await user.click(screen.getByTestId("toggle-item-2"))
            expect(screen.getByTestId("selected-count")).toHaveTextContent("2")
            
            // Exit selection mode
            await user.click(screen.getByTestId("toggle-mode"))
            expect(screen.getByTestId("selected-count")).toHaveTextContent("0")
        })
        
        it("toggles individual item selection", async () => {
            const user = userEvent.setup()
            render(
                <SelectionProvider>
                    <TestConsumer />
                </SelectionProvider>
            )
            
            await user.click(screen.getByTestId("toggle-item-1"))
            expect(screen.getByTestId("selected-ids")).toHaveTextContent("item-1")
            
            await user.click(screen.getByTestId("toggle-item-2"))
            expect(screen.getByTestId("selected-ids")).toHaveTextContent("item-1,item-2")
            
            // Toggle off
            await user.click(screen.getByTestId("toggle-item-1"))
            expect(screen.getByTestId("selected-ids")).toHaveTextContent("item-2")
        })
        
        it("selects all items", async () => {
            const user = userEvent.setup()
            render(
                <SelectionProvider>
                    <TestConsumer />
                </SelectionProvider>
            )
            
            await user.click(screen.getByTestId("select-all"))
            expect(screen.getByTestId("selected-count")).toHaveTextContent("3")
        })
        
        it("deselects all items", async () => {
            const user = userEvent.setup()
            render(
                <SelectionProvider>
                    <TestConsumer />
                </SelectionProvider>
            )
            
            await user.click(screen.getByTestId("select-all"))
            expect(screen.getByTestId("selected-count")).toHaveTextContent("3")
            
            await user.click(screen.getByTestId("deselect-all"))
            expect(screen.getByTestId("selected-count")).toHaveTextContent("0")
        })
    })
    
    describe("useSelectionMode", () => {
        it("provides selection mode state", async () => {
            const user = userEvent.setup()
            render(
                <SelectionProvider>
                    <SelectionModeConsumer />
                </SelectionProvider>
            )
            
            expect(screen.getByTestId("mode-only")).toHaveTextContent("off")
            
            await user.click(screen.getByTestId("toggle-mode-only"))
            expect(screen.getByTestId("mode-only")).toHaveTextContent("on")
        })
    })
    
    describe("useIsSelected", () => {
        it("returns whether an item is selected", async () => {
            const user = userEvent.setup()
            render(
                <SelectionProvider>
                    <TestConsumer />
                    <IsSelectedConsumer id="item-1" />
                    <IsSelectedConsumer id="item-2" />
                </SelectionProvider>
            )
            
            expect(screen.getByTestId("is-selected-item-1")).toHaveTextContent("no")
            expect(screen.getByTestId("is-selected-item-2")).toHaveTextContent("no")
            
            await user.click(screen.getByTestId("toggle-item-1"))
            expect(screen.getByTestId("is-selected-item-1")).toHaveTextContent("yes")
            expect(screen.getByTestId("is-selected-item-2")).toHaveTextContent("no")
        })
    })
    
    describe("error handling", () => {
        it("throws when useSelection is used outside provider", () => {
            // Suppress console.error for this test
            const consoleSpy = vi.spyOn(console, "error").mockImplementation(() => {})
            
            expect(() => {
                render(<TestConsumer />)
            }).toThrow("useSelection must be used within a SelectionProvider")
            
            consoleSpy.mockRestore()
        })
    })
})

"use client"

/**
 * SelectionContext - Isolated selection state for gallery performance
 * 
 * This context isolates selection state changes from parent components,
 * preventing unnecessary re-renders when selection changes. Only components
 * that consume this context will re-render on selection changes.
 * 
 * Performance benefits:
 * - Selection changes don't propagate to StudioClientShell
 * - Parent components don't re-render on checkbox toggles
 * - Uses refs internally to provide stable callbacks
 */

import * as React from "react"

export interface SelectionContextValue {
    // State
    selectionMode: boolean
    selectedIds: Set<string>
    
    // Actions
    toggleSelectionMode: () => void
    toggleSelection: (id: string) => void
    selectAll: (ids: string[]) => void
    deselectAll: () => void
    isSelected: (id: string) => boolean
    
    // Bulk action callbacks (provided by parent for actual operations)
    onDeleteSelected?: () => Promise<void>
    onMakeSelectedPublic?: () => Promise<void>
    onMakeSelectedPrivate?: () => Promise<void>
}

const SelectionContext = React.createContext<SelectionContextValue | null>(null)

export interface SelectionProviderProps {
    children: React.ReactNode
    onDeleteSelected?: () => Promise<void>
    onMakeSelectedPublic?: () => Promise<void>
    onMakeSelectedPrivate?: () => Promise<void>
}

/**
 * Provider for selection state - manages selection internally to avoid
 * propagating state changes to parent components.
 */
export function SelectionProvider({
    children,
    onDeleteSelected,
    onMakeSelectedPublic,
    onMakeSelectedPrivate,
}: SelectionProviderProps) {
    const [selectionMode, setSelectionMode] = React.useState(false)
    const [selectedIds, setSelectedIds] = React.useState<Set<string>>(new Set())
    
    // Ref for stable callback access
    const selectedIdsRef = React.useRef(selectedIds)
    selectedIdsRef.current = selectedIds
    
    // Stable callbacks
    const toggleSelectionMode = React.useCallback(() => {
        setSelectionMode(prev => {
            // Clear selection when exiting selection mode
            if (prev) {
                setSelectedIds(new Set())
            }
            return !prev
        })
    }, [])
    
    const toggleSelection = React.useCallback((id: string) => {
        setSelectedIds(prev => {
            const next = new Set(prev)
            if (next.has(id)) {
                next.delete(id)
            } else {
                next.add(id)
            }
            return next
        })
    }, [])
    
    const selectAll = React.useCallback((ids: string[]) => {
        setSelectedIds(new Set(ids))
    }, [])
    
    const deselectAll = React.useCallback(() => {
        setSelectedIds(new Set())
    }, [])
    
    const isSelected = React.useCallback((id: string) => {
        return selectedIdsRef.current.has(id)
    }, [])
    
    // Memoize context value to prevent unnecessary re-renders
    const value = React.useMemo<SelectionContextValue>(() => ({
        selectionMode,
        selectedIds,
        toggleSelectionMode,
        toggleSelection,
        selectAll,
        deselectAll,
        isSelected,
        onDeleteSelected,
        onMakeSelectedPublic,
        onMakeSelectedPrivate,
    }), [
        selectionMode,
        selectedIds,
        toggleSelectionMode,
        toggleSelection,
        selectAll,
        deselectAll,
        isSelected,
        onDeleteSelected,
        onMakeSelectedPublic,
        onMakeSelectedPrivate,
    ])
    
    return (
        <SelectionContext.Provider value={value}>
            {children}
        </SelectionContext.Provider>
    )
}

/**
 * Hook to access selection context
 */
export function useSelection(): SelectionContextValue {
    const context = React.useContext(SelectionContext)
    if (!context) {
        throw new Error("useSelection must be used within a SelectionProvider")
    }
    return context
}

/**
 * Hook to access only the selection mode state (for components that only
 * need to know if selection mode is active, not the actual selections)
 */
export function useSelectionMode(): { selectionMode: boolean; toggleSelectionMode: () => void } {
    const { selectionMode, toggleSelectionMode } = useSelection()
    return { selectionMode, toggleSelectionMode }
}

/**
 * Hook to check if a specific item is selected (isolated re-render scope)
 */
export function useIsSelected(id: string): boolean {
    const { selectedIds } = useSelection()
    return selectedIds.has(id)
}

