 */
import { render, screen, fireEvent } from "@testing-library/react"
import { describe, it, expect, vi } from "vitest"
import { SensitiveContentOverlay } from "./sensitive-content-overlay"
import { toast } from "sonner"
import { useRouter } from "next/navigation"

// Mock sonner toast
vi.mock("sonner", () => ({
    toast: vi.fn()
}))

// Mock useRouter
const mockPush = vi.fn()
vi.mock("next/navigation", () => ({
    useRouter: () => ({
        push: mockPush
    })
}))

describe("SensitiveContentOverlay", () => {
    it("renders sensitive content warning", () => {
        render(<SensitiveContentOverlay />)
        expect(screen.getByText("Sensitive Content")).toBeInTheDocument()
    })

    describe("Authenticated User (Allowed to Reveal)", () => {
        it("reveals content when clicked", () => {
            const onReveal = vi.fn()
            render(<SensitiveContentOverlay onReveal={onReveal} isAllowedToReveal={true} />)
            
            const overlay = screen.getByText("Sensitive Content").closest("div")?.parentElement
            fireEvent.click(overlay!)
            
            expect(onReveal).toHaveBeenCalled()
        })

        it("shows 'Click to reveal' text", () => {
            render(<SensitiveContentOverlay isAllowedToReveal={true} />)
            expect(screen.getByText("Click to reveal")).toBeInTheDocument()
        })
    })

    describe("Unauthenticated User (Locked)", () => {
        it("triggers toast and does NOT reveal when clicked", () => {
            const onReveal = vi.fn()
            render(<SensitiveContentOverlay onReveal={onReveal} isAllowedToReveal={false} />)
            
            const overlay = screen.getByText("Sign in to view").closest("div")?.parentElement
            fireEvent.click(overlay!)
            
            expect(onReveal).not.toHaveBeenCalled()
            expect(toast).toHaveBeenCalledWith(
                "Please sign in to view sensitive content",
                expect.objectContaining({
                    action: expect.objectContaining({
                        label: "Sign In"
                    })
                })
            )
        })

        it("shows 'Sign in to view' text", () => {
            render(<SensitiveContentOverlay isAllowedToReveal={false} />)
            expect(screen.getByText("Sign in to view")).toBeInTheDocument()
        })

        it("redirects to sign-in when toast action is clicked", () => {
             // We need to simulate the toast action click. 
             // Since we mocked toast to just be a fn, we can capture the args and call onClick.
             render(<SensitiveContentOverlay isAllowedToReveal={false} />)
             const overlay = screen.getByText("Sign in to view").closest("div")?.parentElement
             fireEvent.click(overlay!)

             const toastCall = vi.mocked(toast).mock.calls[0]
             const options = toastCall[1] as any
             
             options.action.onClick()
             expect(mockPush).toHaveBeenCalledWith("/sign-in")
        })
    })
})

"use client"

import { useState } from "react"
import { Eye, EyeOff, AlertTriangle } from "lucide-react"
import { cn } from "@/lib/utils"
import { toast } from "sonner"
import { useRouter } from "next/navigation"

interface SensitiveContentOverlayProps {
    className?: string
    onReveal?: () => void
    isAllowedToReveal?: boolean
}

export function SensitiveContentOverlay({ 
    className,
    onReveal,
    isAllowedToReveal = true
}: SensitiveContentOverlayProps) {
    const [revealed, setRevealed] = useState(false)
    const router = useRouter()
    
    // If local state says revealed, hide overlay (unless it was locked and somehow revealed - theoretically impossible)
    if (revealed) return null
    
    return (
        <div 
            className={cn(
                "absolute inset-0 z-10 flex flex-col items-center justify-center",
                "bg-black/90 backdrop-blur-xl", // Increased opacity and blur
                "rounded-lg cursor-pointer group hover:bg-black/80 transition-all",
                className
            )}
            onClick={(e) => {
                e.preventDefault()
                e.stopPropagation()
                
                if (isAllowedToReveal) {
                    setRevealed(true)
                    onReveal?.()
                } else {
                    toast("Please sign in to view sensitive content", {
                        action: {
                            label: "Sign In",
                            onClick: () => router.push("/sign-in")
                        }
                    })
                }
            }}
        >
            {/* If not allowed to reveal, wrap in Link to sign-in? 
                This might break layout if we wrap the whole div. 
                Instead, we make the onClick trigger navigation.
            */}
            
            <div className="flex flex-col items-center p-4 text-center transform group-hover:scale-105 transition-transform">
                <div className="rounded-full bg-amber-500/20 p-3 mb-3">
                    {isAllowedToReveal ? (
                         <AlertTriangle className="h-6 w-6 text-amber-500" />
                    ) : (
                         <EyeOff className="h-6 w-6 text-amber-500" />
                    )}
                </div>
                <span className="text-white font-semibold text-sm mb-1">
                    {isAllowedToReveal ? "Sensitive Content" : "Sign in to view"}
                </span>
                <span className="text-white/60 text-xs">
                    {isAllowedToReveal ? "Click to reveal" : "Sensitive content hidden"}
                </span>
            </div>
        </div>
    )
}

"use client"

import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"
import { PanelLeftIcon } from "lucide-react"
import * as React from "react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Separator } from "@/components/ui/separator"
import {
    Sheet,
    SheetContent,
    SheetDescription,
    SheetHeader,
    SheetTitle,
} from "@/components/ui/sheet"
import { Skeleton } from "@/components/ui/skeleton"
import {
    Tooltip,
    TooltipContent,
    TooltipProvider,
    TooltipTrigger,
} from "@/components/ui/tooltip"
import { useIsMobile } from "@/hooks/use-mobile"
import { cn } from "@/lib/utils"

const SIDEBAR_COOKIE_NAME = "sidebar_state"
const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7
const SIDEBAR_WIDTH = "16rem"
const SIDEBAR_WIDTH_MOBILE = "18rem"
const SIDEBAR_WIDTH_ICON = "3rem"
const SIDEBAR_KEYBOARD_SHORTCUT = "b"

type SidebarContextProps = {
  state: "expanded" | "collapsed"
  open: boolean
  setOpen: (open: boolean) => void
  openMobile: boolean
  setOpenMobile: (open: boolean) => void
  isMobile: boolean
  toggleSidebar: () => void
}

const SidebarContext = React.createContext<SidebarContextProps | null>(null)

function useSidebar() {
  const context = React.useContext(SidebarContext)
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.")
  }

  return context
}

function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  className,
  style,
  children,
  cookieName = SIDEBAR_COOKIE_NAME,
  ...props
}: React.ComponentProps<"div"> & {
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
  cookieName?: string
}) {
  const isMobile = useIsMobile()
  const [openMobile, setOpenMobileInternal] = React.useState(false)

  // This is the internal state of the sidebar.
  // We use openProp and setOpenProp for control from outside the component.
  const [_open, _setOpen] = React.useState(defaultOpen)
  const open = openProp ?? _open
  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === "function" ? value(open) : value
      if (setOpenProp) {
        setOpenProp(openState)
      } else {
        _setOpen(openState)
      }

      // This sets the cookie to keep the sidebar state.
      document.cookie = `${cookieName}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`
    },
    [setOpenProp, open, cookieName]
  )

  // Track openMobile in a ref to avoid recreating setOpenMobile on every state change
  const openMobileRef = React.useRef(openMobile)
  React.useEffect(() => {
    openMobileRef.current = openMobile
  }, [openMobile])

  // Wrapped setOpenMobile that also notifies the parent (setOpenProp) when on mobile.
  // This ensures bidirectional sync: when the Sheet closes via overlay click,
  // the parent state (e.g., useStudioUI's showLeftSidebar) gets updated.
  // Using ref to avoid recreating this callback on every openMobile change.
  const setOpenMobile = React.useCallback(
    (value: boolean | ((prev: boolean) => boolean)) => {
      const newValue = typeof value === "function" ? value(openMobileRef.current) : value
      setOpenMobileInternal(newValue)
      // Sync back to parent if we have an external handler
      if (setOpenProp) {
        setOpenProp(newValue)
      }
    },
    [setOpenProp]
  )

  // Mobile Sidebar Sync (parent -> mobile):
  // When the open prop changes from an external toggle, sync to mobile state.
  React.useEffect(() => {
    if (isMobile && openProp !== undefined && openProp !== openMobile) {
      setOpenMobileInternal(openProp)
    }
  }, [isMobile, openProp, openMobile])

  // Helper to toggle the sidebar.
  const toggleSidebar = React.useCallback(() => {
    return isMobile ? setOpenMobile((prev) => !prev) : setOpen((prev) => !prev)
  }, [isMobile, setOpen, setOpenMobile])

  // Adds a keyboard shortcut to toggle the sidebar.
  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
        (event.metaKey || event.ctrlKey)
      ) {
        event.preventDefault()
        toggleSidebar()
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [toggleSidebar])

  // We add a state so that we can do data-state="expanded" or "collapsed".
  // This makes it easier to style the sidebar with Tailwind classes.
  const state = open ? "expanded" : "collapsed"

  const contextValue = React.useMemo<SidebarContextProps>(
    () => ({
      state,
      open,
      setOpen,
      isMobile,
      openMobile,
      setOpenMobile,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar]
  )

  return (
    <SidebarContext.Provider value={contextValue}>
      <TooltipProvider delayDuration={0}>
        <div
          data-slot="sidebar-wrapper"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH,
              "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
              ...style,
            } as React.CSSProperties
          }
          className={cn(
            "group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full",
            className
          )}
          {...props}
        >
          {children}
        </div>
      </TooltipProvider>
    </SidebarContext.Provider>
  )
}

function Sidebar({
  side = "left",
  variant = "sidebar",
  collapsible = "offcanvas",
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  side?: "left" | "right"
  variant?: "sidebar" | "floating" | "inset"
  collapsible?: "offcanvas" | "icon" | "none"
}) {
  const { isMobile, state, openMobile, setOpenMobile } = useSidebar()

  if (collapsible === "none") {
    return (
      <div
        data-slot="sidebar"
        className={cn(
          "bg-sidebar text-sidebar-foreground flex h-full w-(--sidebar-width) flex-col",
          className
        )}
        {...props}
      >
        {children}
      </div>
    )
  }

  if (isMobile) {
    return (
      <>
        {/* Overlay - clickable backdrop to close sidebar */}
        {openMobile && (
          <div
            className="fixed inset-0 z-40 bg-black/50 animate-in fade-in-0 duration-200"
            onClick={() => setOpenMobile(false)}
            aria-hidden="true"
          />
        )}
        {/* Always-mounted sidebar container - uses CSS transforms like desktop */}
        <div
          data-sidebar="sidebar"
          data-slot="sidebar"
          data-mobile="true"
          data-state={openMobile ? "expanded" : "collapsed"}
          className={cn(
            "bg-sidebar text-sidebar-foreground fixed inset-y-0 z-50 flex h-svh flex-col transition-transform duration-200 ease-out",
            side === "left" && "left-0",
            side === "right" && "right-0",
            // Transform based on state
            side === "left" && !openMobile && "-translate-x-full",
            side === "right" && !openMobile && "translate-x-full",
            side === "left" && "border-r",
            side === "right" && "border-l",
            className
          )}
          style={{
            width: "var(--sidebar-width)",
          } as React.CSSProperties}
          {...props}
        >
          <div className="flex h-full w-full flex-col">{children}</div>
        </div>
      </>
    )
  }

  return (
    <div
      className="group peer text-sidebar-foreground hidden md:block"
      data-state={state}
      data-collapsible={state === "collapsed" ? collapsible : ""}
      data-variant={variant}
      data-side={side}
      data-slot="sidebar"
    >
      {/* This is what handles the sidebar gap on desktop */}
      <div
        data-slot="sidebar-gap"
        className={cn(
          "relative w-(--sidebar-width) bg-transparent transition-[width] duration-200 ease-linear",
          "group-data-[collapsible=offcanvas]:w-0",
          "group-data-[side=right]:rotate-180",
          variant === "floating" || variant === "inset"
            ? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4)))]"
            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon)"
        )}
      />
      <div
        data-slot="sidebar-container"
        className={cn(
          "fixed inset-y-0 z-10 hidden h-svh w-(--sidebar-width) transition-[left,right,width] duration-200 ease-linear md:flex",
          side === "left"
            ? "left-0 group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)]"
            : "right-0 group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)]",
          // Adjust the padding for floating and inset variants.
          variant === "floating" || variant === "inset"
            ? "p-2 group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4))+2px)]"
            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon) group-data-[side=left]:border-r group-data-[side=right]:border-l",
          className
        )}
        {...props}
      >
        <div
          data-sidebar="sidebar"
          data-slot="sidebar-inner"
          className="bg-sidebar group-data-[variant=floating]:border-sidebar-border flex h-full w-full flex-col group-data-[variant=floating]:rounded-lg group-data-[variant=floating]:border group-data-[variant=floating]:shadow-sm"
        >
          {children}
        </div>
      </div>
    </div>
  )
}

function SidebarTrigger({
  className,
  onClick,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { toggleSidebar } = useSidebar()

  return (
    <Button
      data-sidebar="trigger"
      data-slot="sidebar-trigger"
      variant="ghost"
      size="icon"
      className={cn("size-7", className)}
      onClick={(event) => {
