                preventDefault: vi.fn(),
            } as unknown as React.MouseEvent

            await act(async () => {
                await result.current.handleVideoClick(mockEvent)
            })

            expect(onClick).toHaveBeenCalledWith(mockEvent)
        })

        it("calls play() when video is paused", async () => {
            const onClick = vi.fn()
            const { result } = renderHook(() =>
                useMediaPlayer({
                    url: "https://example.com/video.mp4",
                    isVideo: true,
                    onClick,
                })
            )

            // Attach a mock video element
            const mockVideo = createMockVideo(true) // paused
            ;(result.current.videoRef as React.MutableRefObject<HTMLVideoElement | null>).current = mockVideo

            const mockEvent = {
                preventDefault: vi.fn(),
            } as unknown as React.MouseEvent

            await act(async () => {
                await result.current.handleVideoClick(mockEvent)
            })

            expect(mockVideo.play).toHaveBeenCalled()
            expect(mockVideo.pause).not.toHaveBeenCalled()
            expect(onClick).toHaveBeenCalledWith(mockEvent)
        })

        it("calls pause() when video is playing", async () => {
            const onClick = vi.fn()
            const { result } = renderHook(() =>
                useMediaPlayer({
                    url: "https://example.com/video.mp4",
                    isVideo: true,
                    onClick,
                })
            )

            // Attach a mock video element that is playing
            const mockVideo = createMockVideo(false) // playing
            ;(result.current.videoRef as React.MutableRefObject<HTMLVideoElement | null>).current = mockVideo

            const mockEvent = {
                preventDefault: vi.fn(),
            } as unknown as React.MouseEvent

            await act(async () => {
                await result.current.handleVideoClick(mockEvent)
            })

            expect(mockVideo.pause).toHaveBeenCalled()
            expect(mockVideo.play).not.toHaveBeenCalled()
            expect(onClick).toHaveBeenCalledWith(mockEvent)
        })

        it("handles play() rejection gracefully (AbortError)", async () => {
            const consoleError = vi.spyOn(console, "error").mockImplementation(() => {})
            
            const { result } = renderHook(() =>
                useMediaPlayer({
                    url: "https://example.com/video.mp4",
                    isVideo: true,
                })
            )

            // Create mock video that throws AbortError on play
            const abortError = new DOMException("The play() request was interrupted", "AbortError")
            const mockVideo = {
                paused: true,
                play: vi.fn().mockRejectedValue(abortError),
                pause: vi.fn(),
            } as unknown as HTMLVideoElement
            ;(result.current.videoRef as React.MutableRefObject<HTMLVideoElement | null>).current = mockVideo

            const mockEvent = {
                preventDefault: vi.fn(),
            } as unknown as React.MouseEvent

            // Should not throw
            await act(async () => {
                await result.current.handleVideoClick(mockEvent)
            })

            // AbortError should be silently ignored (not logged)
            expect(consoleError).not.toHaveBeenCalled()
            
            consoleError.mockRestore()
        })

        it("logs non-AbortError play() rejections", async () => {
            const consoleError = vi.spyOn(console, "error").mockImplementation(() => {})
            
            const { result } = renderHook(() =>
                useMediaPlayer({
                    url: "https://example.com/video.mp4",
                    isVideo: true,
                })
            )

            // Create mock video that throws a different error on play
            const networkError = new Error("Network error")
            networkError.name = "NetworkError"
            const mockVideo = {
                paused: true,
                play: vi.fn().mockRejectedValue(networkError),
                pause: vi.fn(),
            } as unknown as HTMLVideoElement
            ;(result.current.videoRef as React.MutableRefObject<HTMLVideoElement | null>).current = mockVideo

            const mockEvent = {
                preventDefault: vi.fn(),
            } as unknown as React.MouseEvent

            await act(async () => {
                await result.current.handleVideoClick(mockEvent)
            })

            // Non-AbortError should be logged
            expect(consoleError).toHaveBeenCalledWith("Video playback error:", networkError)
            
            consoleError.mockRestore()
        })

        it("waits for pending play() before calling pause()", async () => {
            const { result } = renderHook(() =>
                useMediaPlayer({
                    url: "https://example.com/video.mp4",
                    isVideo: true,
                })
            )

            // Create a play promise we can control
            let resolvePlay: () => void
            const playPromise = new Promise<void>((resolve) => {
                resolvePlay = resolve
            })

            // Create mock video
            const mockVideo = {
                paused: true,
                play: vi.fn().mockReturnValue(playPromise),
                pause: vi.fn(),
            } as unknown as HTMLVideoElement
            ;(result.current.videoRef as React.MutableRefObject<HTMLVideoElement | null>).current = mockVideo

            const mockEvent = {
                preventDefault: vi.fn(),
            } as unknown as React.MouseEvent

            // Start playing (async)
            let playClickPromise: Promise<void>
            act(() => {
                playClickPromise = result.current.handleVideoClick(mockEvent)
            })

            // Now change the mock to be "playing"
            Object.defineProperty(mockVideo, "paused", { value: false, writable: true })

            // Click again to pause while play() is still pending
            const pauseClickPromise = act(async () => {
                await result.current.handleVideoClick(mockEvent)
            })

            // Resolve the play promise
            await act(async () => {
                resolvePlay!()
                await playPromise
            })

            // Wait for both click handlers to complete
            await playClickPromise!
            await pauseClickPromise

            // pause() should have been called after play() resolved
            expect(mockVideo.pause).toHaveBeenCalled()
        })
    })

    describe("callback stability", () => {
        it("maintains stable callback references across renders", () => {
            const { result, rerender } = renderHook(() =>
                useMediaPlayer({
                    url: "https://example.com/video.mp4",
                    isVideo: true,
                })
            )

            const firstRender = {
                handleLoad: result.current.handleLoad,
                handleError: result.current.handleError,
                handleVideoLoadedData: result.current.handleVideoLoadedData,
                handleVideoClick: result.current.handleVideoClick,
            }

            rerender()

            // Callbacks should be referentially stable (memoized with useCallback)
            expect(result.current.handleLoad).toBe(firstRender.handleLoad)
            expect(result.current.handleError).toBe(firstRender.handleError)
            expect(result.current.handleVideoLoadedData).toBe(firstRender.handleVideoLoadedData)
            expect(result.current.handleVideoClick).toBe(firstRender.handleVideoClick)
        })

        it("updates callbacks when dependencies change", () => {
            const onLoad1 = vi.fn()
            const onLoad2 = vi.fn()

            const { result, rerender } = renderHook(
                ({ onLoad }) =>
                    useMediaPlayer({
                        url: "https://example.com/video.mp4",
                        isVideo: true,
                        onLoad,
                    }),
                { initialProps: { onLoad: onLoad1 } }
            )

            const firstHandleLoad = result.current.handleLoad

            rerender({ onLoad: onLoad2 })

            // handleLoad should be a new function since onLoad changed
            expect(result.current.handleLoad).not.toBe(firstHandleLoad)
        })
    })
})

"use client"

import * as React from "react"

/**
 * Props for the useMediaPlayer hook
 */
export interface UseMediaPlayerProps {
    /** Media URL - used to reset state when it changes */
    url: string
    /** Whether the content is video (vs image) */
    isVideo: boolean
    /** Callback when media successfully loads */
    onLoad?: (e: React.SyntheticEvent<HTMLImageElement | HTMLVideoElement>) => void
    /** Callback when media fails to load */
    onError?: () => void
    /** Optional click handler to call after play/pause toggle */
    onClick?: (e: React.MouseEvent) => void
}

/**
 * Return type for the useMediaPlayer hook
 */
export interface UseMediaPlayerReturn {
    /** Whether the media is currently loading */
    isLoading: boolean
    /** Whether the media failed to load */
    hasError: boolean
    /** Ref to attach to the video element */
    videoRef: React.RefObject<HTMLVideoElement | null>
    /** Handler for media load events */
    handleLoad: (e: React.SyntheticEvent<HTMLImageElement | HTMLVideoElement>) => void
    /** Handler for media error events */
    handleError: () => void
    /** Handler for video-specific loadeddata event */
    handleVideoLoadedData: (e: React.SyntheticEvent<HTMLVideoElement>) => void
    /**
     * Handler for video click events - safely toggles play/pause.
     * 
     * Properly handles the async nature of video.play() to prevent
     * "The play() request was interrupted by a call to pause()" errors.
     */
    handleVideoClick: (e: React.MouseEvent) => Promise<void>
}

/**
 * Custom hook for managing media player state and video playback.
 * 
 * Handles:
 * - Loading and error states
 * - Video element ref management
 * - Safe play/pause toggling that prevents race conditions
 * 
 * The video play/pause logic properly handles the asynchronous nature of
 * video.play() to prevent "The play() request was interrupted by a call
 * to pause()" errors.
 * 
 * @see https://developer.chrome.com/blog/play-request-was-interrupted
 * 
 * @example
 * ```tsx
 * const { isLoading, hasError, videoRef, handleVideoClick } = useMediaPlayer({
 *   url: videoUrl,
 *   isVideo: true,
 *   onLoad: () => console.log('Loaded!'),
 * });
 * ```
 */
export function useMediaPlayer({
    url,
    isVideo,
    onLoad,
    onError,
    onClick,
}: UseMediaPlayerProps): UseMediaPlayerReturn {
    const [isLoading, setIsLoading] = React.useState(true)
    const [hasError, setHasError] = React.useState(false)
    const videoRef = React.useRef<HTMLVideoElement | null>(null)
    
    // Track pending play operation to prevent race conditions
    // This prevents the "play() interrupted by pause()" error
    const playPromiseRef = React.useRef<Promise<void> | null>(null)

    // Reset loading state and cancel pending operations when URL changes
    React.useEffect(() => {
        setIsLoading(true)
        setHasError(false)
        // Clear any pending play promise reference on URL change
        playPromiseRef.current = null
    }, [url])

    const handleLoad = React.useCallback((e: React.SyntheticEvent<HTMLImageElement | HTMLVideoElement>) => {
        setIsLoading(false)
        onLoad?.(e)
    }, [onLoad])

    const handleError = React.useCallback(() => {
        setIsLoading(false)
        setHasError(true)
        onError?.()
    }, [onError])

    // Handle video-specific load event
    const handleVideoLoadedData = React.useCallback((e: React.SyntheticEvent<HTMLVideoElement>) => {
        handleLoad(e)
    }, [handleLoad])

    /**
     * Safely toggle video play/pause state.
     * 
     * The video.play() method returns a Promise that resolves when playback starts.
     * If pause() is called before that Promise resolves, the browser throws an AbortError.
     * 
     * This handler:
     * 1. Tracks pending play() Promises via a ref
     * 2. Waits for pending play() to resolve before calling pause()
     * 3. Catches and ignores AbortError (expected when rapidly clicking)
     */
    const handleVideoClick = React.useCallback(async (e: React.MouseEvent) => {
        e.preventDefault()
        const video = videoRef.current
        if (!video) {
            onClick?.(e)
            return
        }

        if (video.paused) {
            // Start playback and track the Promise
            const playPromise = video.play()
            playPromiseRef.current = playPromise
            
            try {
                await playPromise
            } catch (error) {
                // AbortError is expected if pause() was called while play() was pending
                // This can happen with rapid clicking or component unmount
                if (error instanceof Error && error.name !== 'AbortError') {
                    console.error('Video playback error:', error)
                }
            } finally {
                // Clear the ref once resolved/rejected
                if (playPromiseRef.current === playPromise) {
                    playPromiseRef.current = null
                }
            }
        } else {
            // Before pausing, wait for any pending play() to resolve
            // This prevents the "interrupted by pause()" error
            const pendingPlay = playPromiseRef.current
            if (pendingPlay) {
                try {
                    await pendingPlay
                } catch {
                    // Ignore - play was already aborted or failed
                }
                playPromiseRef.current = null
            }
            video.pause()
        }
        
        onClick?.(e)
    }, [onClick])

    return {
        isLoading,
        hasError,
        videoRef,
        handleLoad,
        handleError,
        handleVideoLoadedData,
        handleVideoClick,
    }
}

// @vitest-environment jsdom
import { describe, it, expect, vi, beforeEach } from "vitest"
import { renderHook, act, waitFor } from "@testing-library/react"
import { usePromptManager } from "./use-prompt-manager"

// Mock useEnhancePrompt
vi.mock("@/hooks/queries", () => ({
    useEnhancePrompt: vi.fn(() => ({
        enhance: vi.fn(),
        cancel: vi.fn(),
        isEnhancing: false,
    })),
    useSuggestions: vi.fn(() => ({
        suggestions: [],
        isLoading: false,
        fetchSuggestions: vi.fn(),
    })),
}))

describe("usePromptManager", () => {
    beforeEach(() => {
        vi.clearAllMocks()
    })

    it("initializes with default values", () => {
        const { result } = renderHook(() => usePromptManager())

        expect(result.current.promptHistory).toEqual([])
        expect(result.current.suggestions).toEqual([])
        expect(result.current.isLoadingSuggestions).toBe(false)
        expect(result.current.isEnhancingPrompt).toBe(false)
        expect(result.current.isEnhancingNegativePrompt).toBe(false)
        expect(result.current.hasPromptContent).toBe(false)
    })

    it("provides a promptSectionRef", () => {
        const { result } = renderHook(() => usePromptManager())

        expect(result.current.promptSectionRef).toBeDefined()
        expect(result.current.promptSectionRef.current).toBeNull()
    })

    it("adds prompts to history without duplicates", () => {
        const { result } = renderHook(() => usePromptManager())

        act(() => {
            result.current.addToPromptHistory("First prompt")
        })

        expect(result.current.promptHistory).toEqual(["First prompt"])

        act(() => {
            result.current.addToPromptHistory("Second prompt")
        })

        expect(result.current.promptHistory).toEqual(["Second prompt", "First prompt"])

        // Adding duplicate should not change history
        act(() => {
            result.current.addToPromptHistory("First prompt")
        })

        expect(result.current.promptHistory).toEqual(["Second prompt", "First prompt"])
    })

    it("limits history to 10 items", () => {
        const { result } = renderHook(() => usePromptManager())

        // Add 12 unique prompts
        for (let i = 1; i <= 12; i++) {
            act(() => {
                result.current.addToPromptHistory(`Prompt ${i}`)
            })
        }

        expect(result.current.promptHistory.length).toBe(10)
        expect(result.current.promptHistory[0]).toBe("Prompt 12")
        expect(result.current.promptHistory[9]).toBe("Prompt 3")
    })

    it("handles prompt content change", () => {
        const { result } = renderHook(() => usePromptManager())

        expect(result.current.hasPromptContent).toBe(false)

        act(() => {
            result.current.handlePromptContentChange(true)
        })

        expect(result.current.hasPromptContent).toBe(true)

        act(() => {
            result.current.handlePromptContentChange(false)
        })

        expect(result.current.hasPromptContent).toBe(false)
    })

    it("setHasPromptContent updates state", () => {
        const { result } = renderHook(() => usePromptManager())

        act(() => {
            result.current.setHasPromptContent(true)
        })

        expect(result.current.hasPromptContent).toBe(true)
    })

    it("handleSelectHistory updates content state", () => {
        const { result } = renderHook(() => usePromptManager())

        act(() => {
            result.current.handleSelectHistory("A beautiful landscape")
        })

        expect(result.current.hasPromptContent).toBe(true)
    })

    it("handleSelectHistory with empty string sets hasPromptContent to false", () => {
        const { result } = renderHook(() => usePromptManager())

        // First set to true
        act(() => {
            result.current.handleSelectHistory("Something")
        })
        expect(result.current.hasPromptContent).toBe(true)

        // Then set to empty
        act(() => {
            result.current.handleSelectHistory("")
        })

        expect(result.current.hasPromptContent).toBe(false)
    })

    it("getPromptValues returns trimmed values when ref is null", () => {
        const { result } = renderHook(() => usePromptManager())

        const values = result.current.getPromptValues()

        expect(values).toEqual({ prompt: "", negativePrompt: "" })
    })

    it("exposes enhancePrompt callback", () => {
        const { result } = renderHook(() => usePromptManager())

        expect(typeof result.current.enhancePrompt).toBe("function")
    })

    it("exposes cancelEnhancePrompt callback", () => {
        const { result } = renderHook(() => usePromptManager())

        expect(typeof result.current.cancelEnhancePrompt).toBe("function")
    })

    it("exposes enhanceNegativePrompt callback", () => {
        const { result } = renderHook(() => usePromptManager())

        expect(typeof result.current.enhanceNegativePrompt).toBe("function")
    })

    it("exposes cancelEnhanceNegativePrompt callback", () => {
        const { result } = renderHook(() => usePromptManager())

        expect(typeof result.current.cancelEnhanceNegativePrompt).toBe("function")
    })

    it("exposes fetchSuggestions callback", () => {
        const { result } = renderHook(() => usePromptManager())

        expect(typeof result.current.fetchSuggestions).toBe("function")
    })
})

