"use client";

/**
 * Pollen Auth Context
 *
 * React Context provider for managing BYOP (Bring Your Own Pollen) authentication.
 * Provides authentication state and actions throughout the application.
 *
 * This context handles:
 * - Storing and retrieving API keys from localStorage
 * - Tracking authorization expiry
 * - Initiating OAuth flow to Pollinations
 * - Cross-tab synchronization of auth state
 */

import {
  createContext,
  useCallback,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import {
  buildAuthorizationUrl,
  EXPIRING_SOON_THRESHOLD_DAYS,
  getCallbackUrl,
  STORAGE_KEY,
} from "./constants";
import {
  clearStoredAuth,
  getStoredApiKey,
  getStoredMetadata,
  isAuthExpired as checkIsAuthExpired,
  getDaysUntilExpiry as calcDaysUntilExpiry,
  POLLEN_AUTH_CHANGED_EVENT,
  type PollenAuthMetadata,
} from "./storage";

/**
 * State representing the current BYOP authorization.
 */
export interface PollenAuthState {
  /** The BYOP API key (null if not authorized) */
  apiKey: string | null;
  /** Whether the user is currently authorized with a valid key */
  isAuthorized: boolean;
  /** When the current authorization expires (null if not authorized) */
  expiresAt: Date | null;
  /** Days until expiration (null if not authorized) */
  daysUntilExpiry: number | null;
  /** Whether authorization is expiring soon (< threshold days) */
  isExpiringSoon: boolean;
  /** Whether the stored key has expired */
  isExpired: boolean;
  /** Whether the auth state is still being loaded from storage */
  isLoading: boolean;
}

/**
 * Actions available for managing BYOP authorization.
 */
export interface PollenAuthActions {
  /** Initiates OAuth flow to Pollinations */
  authorize: () => void;
  /** Clears stored authorization */
  deauthorize: () => void;
  /** Refreshes auth state from localStorage */
  refreshAuthState: () => void;
}

/**
 * Combined context value type.
 */
export type PollenAuthContextValue = PollenAuthState &
  PollenAuthActions & {
    /**
     * Internal sentinel to detect if this value came from a provider.
     * @internal
     */
    _fromProvider: boolean;
  };

/**
 * Default state when no authorization exists.
 */
const defaultState: PollenAuthState = {
  apiKey: null,
  isAuthorized: false,
  expiresAt: null,
  daysUntilExpiry: null,
  isExpiringSoon: false,
  isExpired: false,
  isLoading: true,
};

/**
 * React Context for Pollen Auth.
 * Initialized with default state and no-op actions.
 */
export const PollenAuthContext = createContext<PollenAuthContextValue>({
  ...defaultState,
  _fromProvider: false,
  authorize: () => {
    console.warn("[PollenAuth] authorize called outside of provider");
  },
  deauthorize: () => {
    console.warn("[PollenAuth] deauthorize called outside of provider");
  },
  refreshAuthState: () => {
    console.warn("[PollenAuth] refreshAuthState called outside of provider");
  },
});

PollenAuthContext.displayName = "PollenAuthContext";

/**
 * Props for the PollenAuthProvider component.
 */
interface PollenAuthProviderProps {
  children: ReactNode;
}

/**
 * Derives auth state from stored API key and metadata.
 */
function deriveAuthState(
  apiKey: string | null,
  metadata: PollenAuthMetadata | null
): Omit<PollenAuthState, "isLoading"> {
  const isExpired = checkIsAuthExpired();
  const daysUntilExpiry = calcDaysUntilExpiry();
  const isAuthorized = Boolean(apiKey) && !isExpired;
  const isExpiringSoon =
    isAuthorized &&
    daysUntilExpiry !== null &&
    daysUntilExpiry <= EXPIRING_SOON_THRESHOLD_DAYS;

  return {
    apiKey: isAuthorized ? apiKey : null,
    isAuthorized,
    expiresAt: metadata ? new Date(metadata.expiresAt) : null,
    daysUntilExpiry,
    isExpiringSoon,
    isExpired: Boolean(apiKey) && isExpired,
  };
}

/**
 * Provider component for BYOP authentication.
 *
 * Wrap your application or Studio layout with this provider to enable
 * BYOP authentication throughout the component tree.
 *
 * @example
 * ```tsx
 * <PollenAuthProvider>
 *   <App />
 * </PollenAuthProvider>
 * ```
 */
export function PollenAuthProvider({ children }: PollenAuthProviderProps) {
  const [state, setState] = useState<PollenAuthState>(defaultState);

  /**
   * Loads auth state from localStorage.
   */
  const loadAuthState = useCallback(() => {
    const apiKey = getStoredApiKey();
    const metadata = getStoredMetadata();
    const derivedState = deriveAuthState(apiKey, metadata);

    setState({
      ...derivedState,
      isLoading: false,
    });
  }, []);

  /**
   * Initiates the OAuth flow by redirecting to Pollinations.
   */
  const authorize = useCallback(() => {
    const callbackUrl = getCallbackUrl();
    const authUrl = buildAuthorizationUrl(callbackUrl);
    window.location.href = authUrl;
  }, []);

  /**
   * Clears the stored authorization and resets state.
   */
  const deauthorize = useCallback(() => {
    clearStoredAuth();
    setState({
      ...defaultState,
      isLoading: false,
    });
  }, []);

  /**
   * Refreshes auth state from localStorage.
   * Useful after callback handler stores new key.
   */
  const refreshAuthState = useCallback(() => {
    loadAuthState();
  }, [loadAuthState]);

  // Initialize auth state on mount
  useEffect(() => {
    loadAuthState();
  }, [loadAuthState]);

  // Listen for storage changes from other tabs (native storage event)
  // and same-tab changes (custom event dispatched by storage utilities)
  useEffect(() => {
    const handleStorageChange = (event: StorageEvent) => {
      if (event.key === STORAGE_KEY || event.key === null) {
        // Key changed or storage was cleared
        loadAuthState();
      }
    };

    // Handle same-tab storage changes via custom event
    const handleAuthChanged = () => {
      loadAuthState();
    };

    window.addEventListener("storage", handleStorageChange);
    window.addEventListener(POLLEN_AUTH_CHANGED_EVENT, handleAuthChanged);
    return () => {
      window.removeEventListener("storage", handleStorageChange);
      window.removeEventListener(POLLEN_AUTH_CHANGED_EVENT, handleAuthChanged);
    };
  }, [loadAuthState]);

  // Memoize context value to prevent unnecessary re-renders
  const contextValue = useMemo<PollenAuthContextValue>(
    () => ({
      ...state,
      _fromProvider: true,
      authorize,
      deauthorize,
      refreshAuthState,
    }),
    [state, authorize, deauthorize, refreshAuthState]
  );

  return (
    <PollenAuthContext.Provider value={contextValue}>
      {children}
    </PollenAuthContext.Provider>
  );
}

import type { GeneratedImage } from "@/types/pollinations";

/**
 * DeepPartial type helper for nested partial objects
 */
export type DeepPartial<T> = {
    [P in keyof T]?: T[P] extends object ? DeepPartial<T[P]> : T[P];
};

/**
 * Creates a mock GeneratedImage object for testing.
 * Includes all required parameters with sensible defaults.
 */
export function createMockImage(overrides: DeepPartial<GeneratedImage> = {}): GeneratedImage {
    const prompt = overrides.prompt || "A beautiful sunset";
    const id = overrides.id || "test-image-1";

    const defaultParams = {
        prompt,
        model: "zimage",
        width: 1024,
        height: 1024,
        enhance: false,
        quality: "medium",
        private: false,
        nologo: false,
        nofeed: false,
        safe: false,
        transparent: false,
    };

    // Merge default params with any overrides provided in params
    const mergedParams = {
        ...defaultParams,
        ...(overrides.params || {}),
    };

    return {
        id,
        url: overrides.url || "https://example.com/image.jpg",
        prompt,
        timestamp: overrides.timestamp || Date.now(),
        params: mergedParams as any,
        ...(overrides as any),
    };
}

import { ConvexHttpClient } from "convex/browser";
import { api } from "../convex/_generated/api";
import * as dotenv from "dotenv";
import ffmpegStatic from "ffmpeg-static";
import ffmpeg from "fluent-ffmpeg";
import { tmpdir } from "os";
import { join } from "path";
import { writeFile, unlink, readFile, mkdir } from "fs/promises";
import { randomUUID } from "crypto";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";

// Load environment variables from .env.local
dotenv.config({ path: ".env.local" });

const client = new ConvexHttpClient(process.env.NEXT_PUBLIC_CONVEX_URL!);

// Helper: Extract Thumbnail Locally
async function extractLocalThumbnail(videoBuffer: Buffer): Promise<Buffer> {
    if (ffmpegStatic) ffmpeg.setFfmpegPath(ffmpegStatic);

    const tempDir = join(tmpdir(), "pixelstream-migration");
    await mkdir(tempDir, { recursive: true });

    const inputPath = join(tempDir, `input-${randomUUID()}.mp4`);
    const outputPath = join(tempDir, `output-${randomUUID()}.jpg`);

    try {
        await writeFile(inputPath, videoBuffer);

        await new Promise<void>((resolve, reject) => {
            ffmpeg(inputPath)
                .seekInput(0.5)
                .frames(1)
                .outputOptions([
                    "-vf", `crop=min(iw\\,ih):min(iw\\,ih),scale=128:128`,
                    "-q:v", "6", // ~80% quality (0-31 scale, lower value is better quality)
                ])
                .output(outputPath)
                .on("end", () => resolve())
                .on("error", (err) => reject(err))
                .run();
        });

        return await readFile(outputPath);
    } finally {
        await unlink(inputPath).catch(() => { });
        await unlink(outputPath).catch(() => { });
    }
}

// Helper: S3 Upload
async function uploadToR2Raw(buffer: Buffer, key: string, contentType: string) {
    const accessKeyId = process.env.R2_ACCESS_KEY_ID;
    const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
    const bucket = process.env.R2_BUCKET_NAME;
    // Fallback to constructing endpoint if not explicitly provided
    const endpoint = process.env.R2_ENDPOINT || `https://${process.env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com`;
    const publicUrl = process.env.R2_PUBLIC_URL;

    if (!accessKeyId || !secretAccessKey || !bucket || !endpoint || !publicUrl) {
        throw new Error("Missing R2 environment variables");
    }

    const s3 = new S3Client({
        region: "auto",
        endpoint: endpoint,
        credentials: {
            accessKeyId,
            secretAccessKey,
        },
    });

    await s3.send(new PutObjectCommand({
        Bucket: bucket,
        Key: key,
        Body: buffer,
        ContentType: contentType,
        CacheControl: "public, max-age=31536000, immutable",
    }));

    return `${publicUrl}/${key}`;
}

async function main() {
    console.log("🚀 Starting Local Migration Script (FULL REGENERATION MODE)...");
    console.log("   Quality set to ~80% (low artifacting)");

    let cursor: string | null = null;
    let isDone = false;
    let totalProcessed = 0;

    // Process until done
    while (!isDone) {
        // Fetch Batch with pagination
        // @ts-ignore - paginationOpts type is any in definition
        const result = await client.query(api.thumbnailMigration.getAllImagesBatch, {
            paginationOpts: {
                numItems: 20,
                cursor: cursor
            }
        });

        const batch = result.page;
        cursor = result.continueCursor;
        isDone = result.isDone;

        if (batch.length === 0) {
            console.log("✅ No more images returned. Migration complete.");
            break;
        }

        console.log(`Processing batch of ${batch.length}... (Total so far: ${totalProcessed})`);

        for (const image of batch) {
            try {
                process.stdout.write(`   Processing: ${image._id} (${image.contentType})... `);

                // Fetch Original
                const res = await fetch(image.url);
                if (!res.ok) throw new Error(`Fetch failed: ${res.status}`);
                const buffer = Buffer.from(await res.arrayBuffer());

                let thumbnailBuffer: Buffer;

                if (image.contentType.startsWith("video/")) {
                    thumbnailBuffer = await extractLocalThumbnail(buffer);
                } else {
                    // Use Jimp for images
                    const { Jimp } = await import("jimp");
                    const jimg = await Jimp.read(buffer);

                    // Crop and resize
                    const dim = Math.min(jimg.width, jimg.height);
                    jimg.crop({
                        x: (jimg.width - dim) / 2,
                        y: (jimg.height - dim) / 2,
                        w: dim, h: dim
                    });
                    jimg.resize({ w: 128, h: 128 });

                    // Increased quality to 80 to reduce artifacts
                    thumbnailBuffer = await jimg.getBuffer("image/jpeg", { quality: 80 });
                }

                // Upload
                const thumbKey = image.r2Key.replace(/^generated\//, "thumbnails/");
                const thumbUrl = await uploadToR2Raw(thumbnailBuffer, thumbKey, "image/jpeg");

                // Mutate
                await client.mutation(api.thumbnailMigration.updateImageThumbnail, {
                    imageId: image._id,
                    thumbnailR2Key: thumbKey,
                    thumbnailUrl: thumbUrl
                });

                console.log("✅ Done");

            } catch (e: any) {
                console.log(`❌ Failed: ${e.message || e}`);
            }
        }
        totalProcessed += batch.length;
    }

    console.log(`\n🎉 Migration successfully finished! Processed ${totalProcessed} images/videos.`);
}

main().catch(console.error);
